insert into ponew values
(1, 1, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The Subjective Global Assessment (SGA) classifies nutritional status using:', '["History (weight loss, intake, GI symptoms, function) plus examination", "Body mass index alone, calculated from height and weight", "Blood glucose and HbA1c measured on the first ICU day", "Serum albumin alone, measured on admission and weekly"]'::jsonb, 0, 'Patients are graded A (well nourished), B (moderate) or C (severely malnourished).', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 2, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Ventilation-perfusion (V/Q) mismatch during anaesthesia can result in:', '["No clinical effect", "Only affecting blood pressure, not oxygenation", "Improved gas exchange", "Impaired oxygenation despite adequate ventilator settings"]'::jsonb, 3, 'A mismatch between ventilated alveoli and perfused capillaries impairs effective gas exchange, contributing to hypoxaemia even with seemingly adequate ventilation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 3, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A common electrolyte complication of plasmapheresis, related to the citrate anticoagulant used in the extracorporeal circuit, is:', '["Hypocalcaemia (citrate toxicity), with perioral tingling", "Hyperphosphataemia from cell breakdown", "Hyperkalaemia from haemolysis in the circuit", "Hypernatraemia from the replacement fluid"]'::jsonb, 0, 'Citrate used to anticoagulate the apheresis circuit chelates calcium, and some enters the systemic circulation, commonly causing symptomatic hypocalcemia such as perioral or extremity paresthesia and cramps; calcium supplementation is often given prophylactically or as needed.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 4, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The earliest and most sensitive sign of malignant hyperthermia under anaesthesia is usually:', '["Dark, cola-coloured urine output", "An unexplained rise in end-tidal CO₂", "A core temperature above 40 °C", "A sudden fall in blood glucose"]'::jsonb, 1, 'Hypermetabolism raises CO2 production before temperature rises. Hyperthermia is often a late sign. Masseter rigidity after suxamethonium is another early warning.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 5, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Pulse oximetry measures:', '["Respiratory rate directly from chest wall movement", "Partial pressure of carbon dioxide in arterial blood", "Haemoglobin concentration in grams per decilitre", "Oxygen saturation of arterial haemoglobin by light absorption"]'::jsonb, 3, 'Readings are unreliable with poor perfusion, cold fingers, nail polish, carbon monoxide poisoning and motion. A normal SpO2 does not guarantee adequate ventilation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 6, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Latex allergy among theatre staff is managed by:', '["Taking antihistamines every day", "Using powdered latex gloves instead", "Ignoring mild skin symptoms", "Using latex-free gloves and equipment"]'::jsonb, 3, 'Latex allergy can cause contact dermatitis or anaphylaxis.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 7, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A patient experiences postoperative ileus. What intervention should the nurse prioritize?', '["Withholding nutrition", "Increasing fiber intake", "Encouraging early ambulation", "Administering laxatives"]'::jsonb, 2, 'Early ambulation promotes return of normal peristalsis in postoperative ileus.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 8, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Surgical smoke from diathermy should be:', '["Blown away from the field with fans", "Ignored, as masks filter all of it", "Inhaled by staff, as it is harmless", "Removed with smoke evacuation"]'::jsonb, 3, 'Smoke contains chemicals and possibly viruses.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 9, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Hazardous substances in theatre (e.g. formaldehyde, glutaraldehyde) are controlled under:', '["Risk assessment (COSHH), PPE and ventilation", "No regulations, as they are hospital chemicals", "Each staff member''s own personal discretion", "Patient consent before any chemical is used"]'::jsonb, 0, 'Material safety data sheets give information on handling.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 10, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Critical thinking in ICU nursing involves:', '["Following every order exactly without any thought", "Analysing data, questioning assumptions, reasoned decisions", "Relying only on memory for all clinical decisions", "Avoiding decisions and waiting for others to act"]'::jsonb, 1, 'It improves patient safety.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 11, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'In toxic epidermal necrolysis, more than 30% of the body surface is detached. ICU care is similar to:', '["Major burns: fluids, warmth, wound care, infection control, nutrition", "A simple allergy: antihistamines and observation on the ward", "Cellulitis: oral antibiotics and elevation of the limbs", "Eczema: emollients and topical steroids at home"]'::jsonb, 0, 'Stop the culprit drug. SCORTEN predicts mortality.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 12, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Rapid sequence induction is primarily indicated for patients:', '["With no comorbidities", "Undergoing elective minor surgery", "At high risk of pulmonary aspiration", "Who are fasted for over 12 hours"]'::jsonb, 2, 'RSI minimises the time between loss of airway reflexes and securing the airway, protecting patients at high aspiration risk (e.g. full stomach, bowel obstruction, pregnancy) from regurgitation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 13, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Prevention of Mendelson''s syndrome in an emergency caesarean section includes:', '["Antacids, H2 blockers, RSI and cricoid pressure", "Avoiding pre-oxygenation to save time", "A large meal two hours before surgery", "Inhalational induction with a face mask"]'::jsonb, 0, 'Pregnant women have delayed gastric emptying and lax lower oesophageal sphincter.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 14, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Before induction, the anaesthetic nurse ensures the following is immediately available:', '["The discharge letter and the next day''s theatre list", "The surgical instruments", "The patient''s breakfast", "Working suction, airway equipment and emergency drugs"]'::jsonb, 3, 'Check the laryngoscope light and spare blades.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 15, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Calorie needs of a critically ill adult in the early phase are about:', '["5 kcal/kg/day", "100 kcal/kg/day", "20–25 kcal/kg/day", "50 kcal/kg/day"]'::jsonb, 2, 'Overfeeding causes hyperglycaemia and increases CO₂ production.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 16, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'What intervention is beneficial in preventing stroke in a postoperative patient in the ICU?', '["Encouraging ambulation", "Administering anticoagulants", "Monitoring temperature", "Limiting fluid intake"]'::jsonb, 1, 'Prophylactic anticoagulation reduces thromboembolic stroke risk in patients at elevated risk postoperatively.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 17, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Standard precautions apply to:', '["All patients, whatever the diagnosis", "Only patients with a fever", "Only patients known to be HIV-positive", "Only children and the elderly"]'::jsonb, 0, 'These include hand hygiene, PPE, safe sharps handling and waste management.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 18, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A health talk to relatives of ICU patients should be:', '["Full of medical terms and abbreviations", "Given without any preparation", "Simple, short and with time for questions", "Very long, without any breaks"]'::jsonb, 2, 'Effective communication reduces anxiety.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 19, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The correct order of the classic phases of general anaesthesia is:', '["Maintenance, induction, emergence", "Induction, maintenance, emergence (recovery)", "Emergence, induction, maintenance", "Induction, emergence, maintenance"]'::jsonb, 1, 'Induction takes the patient from awake to anaesthetised, maintenance keeps a stable depth during surgery, and emergence returns the patient to consciousness with protective reflexes.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 20, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which condition is a well-established indication for therapeutic plasma exchange?', '["Simple dehydration", "Mild hyperkalemia", "Thrombotic thrombocytopenic purpura (TTP)", "Uncomplicated urinary tract infection"]'::jsonb, 2, 'TTP is a classic indication for urgent plasma exchange, which removes large von Willebrand factor multimers and autoantibodies against ADAMTS13 while replacing the deficient enzyme via donor plasma.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 21, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Fire drills in theatre are important because:', '["Fires never happen in theatre", "They waste time", "They replace fire extinguishers", "Staff need to know evacuation routes and roles"]'::jsonb, 3, 'Plan evacuation of anaesthetised patients.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 22, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Parenteral nutrition via a central line requires:', '["Strict asepsis, a dedicated lumen and glucose checks", "No need for blood glucose monitoring", "Sharing the lumen with blood transfusions", "Hanging each bag for up to 72 hours"]'::jsonb, 0, 'Line infection and hyperglycaemia are common complications.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 23, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Cricoid pressure (Sellick manoeuvre) during rapid sequence induction is applied to:', '["Push the larynx forward so the cords are seen in every patient", "Compress the oesophagus against the vertebra to reduce regurgitation", "Close the glottis so that bronchospasm cannot occur at intubation", "Stop the patient coughing on the tube as the cuff is inflated"]'::jsonb, 1, 'Firm backward pressure on the cricoid ring (about 30 N once unconscious) occludes the upper oesophagus. It is released only on the anaesthetist''s instruction after cuff inflation and confirmation of tube position.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 24, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Workplace violence and aggression should be:', '["Ignored, unless the nurse is physically injured", "Accepted as part of the job in a busy hospital", "Reported and managed with policies and training", "Handled alone by the nurse without telling anyone"]'::jsonb, 2, 'Staff safety is a management responsibility.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 25, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Enteral feeding should be started in a critically ill patient:', '["Only when the patient asks for food", "Within 24–48 hours, once haemodynamically stable", "Only after the patient has been extubated", "Only after two weeks of IV fluids alone"]'::jsonb, 1, 'Early feeding maintains gut integrity.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 26, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which one of the following drugs increase the serum potassium', '["Atracurium", "Xylocaine", "Succinylcholine", "Pancuronium"]'::jsonb, 2, 'Succinylcholine causes a transient rise in serum potassium as part of its depolarising action, a concern in patients at risk of hyperkalaemia.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 27, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Before transferring a patient to theatre, the ward nurse confirms that:', '["Consent, ID band, site mark, fasting and allergies are checked", "The relatives have started the IV fluids on the ward", "The patient has eaten a light meal for energy before surgery", "All jewellery, dentures and hearing aids are left in place"]'::jsonb, 0, 'A preoperative checklist reduces wrong-patient and wrong-site errors and ensures dentures, prostheses and jewellery are removed or documented.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 28, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A good working posture when using a computer at the nurses'' station includes:', '["Feet dangling", "Screen at eye level and feet flat on the floor", "Twisting the back to reach the keyboard", "Screen far below eye level"]'::jsonb, 1, 'Regular breaks reduce strain.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 29, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A heat and moisture exchanger (HME) filter in the breathing circuit:', '["Adds volatile agent to the gas", "Warms and humidifies inspired gas and filters microbes", "Measures oxygen concentration", "Removes CO₂ from expired gas in place of soda lime"]'::jsonb, 1, 'Check it does not become blocked with secretions.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 30, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Sharps injuries should be reported mainly so that:', '["The patient is informed only", "The ward is closed", "Risk can be assessed, treatment given and practices improved", "The nurse is punished"]'::jsonb, 2, 'Under-reporting hides risks.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 31, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Hypoxia during general anaesthesia refers to:', '["Inadequate oxygen delivery to tissues", "Low blood glucose", "Excess oxygen delivery to tissues", "Elevated body temperature"]'::jsonb, 0, 'Hypoxia is inadequate tissue oxygenation, a critical complication to detect and correct promptly during anaesthesia.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 32, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Culture and sensitivity results are used to:', '["Diagnose viral infections such as flu", "Start antibiotics only after seven days", "Avoid giving any antibiotics at all", "Narrow antibiotics to the most effective agent"]'::jsonb, 3, 'Antimicrobial stewardship reduces resistance.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 33, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Total intravenous anaesthesia (TIVA) uses:', '["Only local anaesthetic infiltrated by the surgeon", "Volatile agents given through a laryngeal mask", "IV infusions such as propofol and remifentanil only", "Only nitrous oxide and oxygen through a face mask"]'::jsonb, 2, 'TIVA reduces postoperative nausea and vomiting and avoids MH triggers. It requires reliable IV access that must be visible and secure throughout.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 34, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Poor operating table height for the scrub nurse may cause:', '["Eye infection", "Skin cancer", "Hearing loss", "Neck, shoulder and back strain"]'::jsonb, 3, 'Adjust the table or use a platform.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 35, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A characteristic side effect of alpha-2 adrenergic agonists such as dexmedetomidine is:', '["Tachycardia", "Malignant hyperthermia", "Bradycardia and hypotension", "Severe bronchospasm"]'::jsonb, 2, 'Alpha-2 agonists (dexmedetomidine, clonidine, xylazine) give sedation with some analgesia but can cause bradycardia and hypotension.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 36, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The functional unit of the kidney responsible for filtration is the:', '["Ureter", "Nephron", "Renal pelvis", "Bladder trigone"]'::jsonb, 1, 'The nephron, comprising the glomerulus and its associated tubules, is the kidney''s basic functional/filtering unit.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 37, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'During embryological development, nervous tissue organisation ultimately gives rise to the:', '["Endocrine system exclusively", "Skeletal system exclusively", "Cardiovascular system only", "Central and peripheral nervous systems"]'::jsonb, 3, 'Nervous tissue development and organisation gives rise to both the central (brain, spinal cord) and peripheral nervous systems.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 38, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which nerve innervates the diaphragm?', '["Radial nerve", "Median nerve", "Phrenic nerve", "Vagus nerve"]'::jsonb, 2, 'The phrenic nerve (C3–C5) supplies the diaphragm: "C3, 4, 5 keep the diaphragm alive".', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 39, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A patient''s arterial blood gas shows low PaO2 despite adequate ventilation. The nurse considers that this could reflect a problem with:', '["The urinary bladder", "Gaseous exchange at the alveolar-capillary membrane", "The endocrine pancreas", "The heart''s electrical conduction system only"]'::jsonb, 1, 'Impaired oxygenation despite adequate ventilation often reflects a gas exchange problem at the alveolar-capillary membrane (e.g. from fluid, inflammation or V/Q mismatch), rather than a ventilation problem itself.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 40, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'In an emergency when the recipient''s blood group is unknown, the red cells that can be given are:', '["Group A Rh-negative", "Group O Rh-negative", "Group B Rh-positive", "Group AB Rh-positive"]'::jsonb, 1, 'Group O red cells have no A or B antigens; Rh-negative avoids sensitisation (important in girls and women of childbearing age). Group AB is the universal plasma donor.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 41, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Cells of which layer of the epidermis are keratinised and dead?', '["Stratum granulosum", "Stratum corneum", "Stratum spinosum", "Stratum basale"]'::jsonb, 1, 'The stratum corneum, the outermost layer, is made of dead keratinised cells.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 42, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Blood flows from the right atrium to the right ventricle through which valve?', '["Bicuspid (mitral)", "Tricuspid", "Pulmonary", "Aortic"]'::jsonb, 1, 'The right atrioventricular valve is the tricuspid valve. The left is the mitral (bicuspid).', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 43, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The pancreas functions as both an endocrine and exocrine organ; insulin is an example of its:', '["Endocrine function", "Only a digestive enzyme", "Neither function", "Exocrine function"]'::jsonb, 0, 'Insulin, secreted by the islets of Langerhans directly into the bloodstream, exemplifies the pancreas''s endocrine function, distinct from its exocrine secretion of digestive enzymes into the duodenum.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 44, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The brain uses about what percentage of the body''s oxygen consumption?', '["20%", "15%", "5%", "10%"]'::jsonb, 0, 'The brain is about 2% of body weight but uses about 20% of the body''s oxygen.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 45, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which of the following cells are in almost constant mitosis?', '["Renal cells", "Nerve cells", "Gastric epithelial cells", "Skeletal muscle cells"]'::jsonb, 2, 'Epithelial lining cells, such as gastric and intestinal mucosa, renew constantly by mitosis. Neurons and cardiac and skeletal muscle rarely divide.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 46, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'After a chest injury, ABGs show pH 7.26, PaCO2 52 mmHg, HCO3 25 mmol/L. This is:', '["Respiratory alkalosis", "Respiratory acidosis", "Metabolic alkalosis", "Metabolic acidosis"]'::jsonb, 1, 'Low pH (acidosis), high PaCO2 (respiratory cause) and normal HCO3 (not yet compensated): acute respiratory acidosis.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 47, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Gastrointestinal glandular secretions primarily aid in:', '["Filtering blood", "Regulating body temperature exclusively", "Producing red blood cells", "Chemical breakdown of food and enzymatic digestion"]'::jsonb, 3, 'GI glands (salivary, gastric, pancreatic, liver/bile) secrete enzymes and other substances essential for chemically breaking down food.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 48, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which of the following are fewest in number but largest in diameter?', '["Alveolar ducts", "Tertiary bronchi", "Alveoli", "Terminal bronchioles"]'::jsonb, 1, 'Tertiary (segmental) bronchi are the widest and fewest of these. The airways get narrower and more numerous towards the alveoli.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 49, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The largest air passages that take part in gas exchange are the:', '["Alveolar ducts", "Terminal bronchioles", "Respiratory bronchioles", "Primary bronchi"]'::jsonb, 2, 'Respiratory bronchioles are the first, and largest, airways with alveoli in their walls, where gas exchange begins.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 50, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Gaseous exchange in the lungs occurs primarily at the level of the:', '["Larynx", "Bronchi", "Trachea", "Alveoli"]'::jsonb, 3, 'The alveoli, with their thin walls and rich capillary network, are the site of gas exchange between air and blood.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 51, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which factor does NOT directly affect the rate or depth of respiration?', '["Blood CO2 levels", "Blood O2 levels", "Blood pH", "Blood glucose level"]'::jsonb, 3, 'Respiration is primarily regulated by chemoreceptors sensing CO2, pH and O2 levels — blood glucose has no direct regulatory role in respiratory drive.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 52, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Hoarseness of voice after thyroidectomy is most likely due to injury of the:', '["Recurrent laryngeal nerve", "Accessory nerve", "Phrenic nerve", "Hypoglossal nerve"]'::jsonb, 0, 'The recurrent laryngeal nerve supplies all intrinsic laryngeal muscles except cricothyroid. Unilateral injury causes hoarseness; bilateral injury can cause stridor and airway obstruction after extubation.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 53, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Filtration of blood in the nephron primarily occurs at the:', '["Loop of Henle", "Glomerulus", "Distal convoluted tubule", "Collecting duct"]'::jsonb, 1, 'The glomerulus, a capillary tuft within Bowman''s capsule, is the site of filtration of plasma into the nephron.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 54, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Cranial nerves originate directly from the:', '["Autonomic ganglia only", "Brain and brainstem", "Spinal cord only", "Peripheral muscles"]'::jsonb, 1, 'The 12 pairs of cranial nerves arise directly from the brain and brainstem, unlike spinal nerves which arise from the spinal cord.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 55, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The part of the ear that functions in both hearing and balance is the:', '["Eustachian tube", "Middle ear", "Inner ear", "Outer ear"]'::jsonb, 2, 'The inner ear holds the cochlea (hearing) and the vestibular apparatus (balance).', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 56, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which female structure is homologous to the male penis?', '["Vagina", "Urethra", "Clitoris", "Ovary"]'::jsonb, 2, 'The clitoris develops from the same embryonic tissue (genital tubercle) as the penis.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 57, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Cardiac output is calculated as:', '["Heart rate multiplied by stroke volume", "Mean arterial pressure divided by heart rate", "Heart rate divided by stroke volume", "Stroke volume minus heart rate"]'::jsonb, 0, 'Cardiac output (CO) = heart rate (HR) x stroke volume (SV), representing the volume of blood pumped by the heart per minute.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 58, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Vital cardiorespiratory centres are located in the:', '["Occipital lobe", "Cerebellum", "Hypothalamus only", "Medulla oblongata"]'::jsonb, 3, 'The medulla oblongata houses the cardiac and respiratory centres that regulate heart rate, blood pressure, and breathing rhythm.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 59, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The brachial plexus is formed from the anterior rami of spinal nerves:', '["T1 to T6", "C3 to C7", "C5 to T1", "C1 to C4"]'::jsonb, 2, 'The brachial plexus supplies the upper limb. It is at risk from shoulder abduction beyond 90°, the lateral and prone positions, and arm board malposition during surgery.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 60, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The olfactory nerve is responsible for:', '["Hearing", "Taste", "Smell", "Vision"]'::jsonb, 2, 'The olfactory nerve (CN I) carries the sense of smell.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 61, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which skin cells alert the immune system to pathogens?', '["Dendritic (Langerhans) cells", "Tactile (Merkel) cells", "Melanocytes", "Keratinocytes"]'::jsonb, 0, 'Dendritic (Langerhans) cells in the epidermis capture antigens and alert the immune system.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 62, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The diaphragm is supplied by the phrenic nerve, which arises from the spinal roots:', '["C3, C4 and C5", "C6, C7 and C8", "T1 to T6", "C1 and C2"]'::jsonb, 0, '''C3, 4, 5 keeps the diaphragm alive.'' High cervical cord injury or phrenic nerve injury (e.g. during neck or thoracic surgery) can cause diaphragmatic paralysis.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 63, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The normal adult blood volume is approximately:', '["40 mL/kg (about 3 L)", "20 mL/kg (about 1.5 L)", "70 mL/kg (about 5 L in an adult)", "150 mL/kg (about 10 L)"]'::jsonb, 2, 'Adult blood volume is about 70 mL/kg (65 in women, 75 in men); about 80–90 mL/kg in infants. It is used to estimate allowable blood loss.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 64, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The brainstem consists of:', '["Hindbrain, ventricle and pons", "Midbrain, hindbrain and forebrain", "Midbrain, pons and forebrain", "Midbrain, pons and medulla"]'::jsonb, 3, 'The brainstem consists of the midbrain, pons and medulla oblongata.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 65, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Antibodies belong to which class of plasma proteins?', '["Gamma globulins", "Albumins", "Alpha globulins", "Agglutinins"]'::jsonb, 0, 'Antibodies (immunoglobulins) are gamma globulins.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 66, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Negative feedback, as a mechanism of hormonal control, means that:', '["Feedback only applies to the nervous system, never hormones", "Hormone levels are entirely independent of blood concentration", "Rising hormone/product levels suppress further release, keeping levels in a stable range", "Rising hormone levels stimulate even more hormone release, with no limit"]'::jsonb, 2, 'Negative feedback is the most common hormonal regulation mechanism: rising levels of a hormone or its effect suppress further release, maintaining homeostasis.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 67, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The portion of the cervix that protrudes into the vagina is covered by:', '["Squamous epithelium", "Transitional epithelium", "Cuboidal epithelium", "Columnar epithelium"]'::jsonb, 0, 'The ectocervix, the part protruding into the vagina, is covered by stratified squamous epithelium. The endocervical canal is lined by columnar epithelium.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 68, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The left anterior descending (LAD) coronary artery mainly supplies:', '["The right ventricle and the SA node in most people", "The inferior wall of the heart and the AV node in most people", "The posterior wall of the left ventricle and the left atrium", "The anterior left ventricle and anterior two-thirds of the septum"]'::jsonb, 3, 'The LAD (from the left main) supplies the anterior LV and most of the septum. The right coronary artery supplies the RV, the inferior wall and, in most people, the SA and AV nodes.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 69, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'From lateral to medial, the contents of the femoral triangle are:', '["Femoral vein, femoral artery, femoral nerve (then canal)", "Femoral nerve, femoral artery, femoral vein (then the femoral canal)", "Femoral artery, femoral nerve, femoral vein (then canal)", "Femoral canal, femoral vein, femoral artery, femoral nerve"]'::jsonb, 1, 'Mnemonic NAVY (Nerve, Artery, Vein, Y-fronts/empty space) from lateral to medial. The femoral pulse is felt at the mid-inguinal point; the vein lies medial for femoral line insertion.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 70, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'After splenectomy, a patient is at greatest risk of overwhelming infection from:', '["Mycobacterium tuberculosis reactivation", "Encapsulated bacteria such as Streptococcus pneumoniae", "Herpes simplex and other viruses", "Candida albicans and other fungi"]'::jsonb, 1, 'The spleen filters encapsulated organisms (pneumococcus, Haemophilus influenzae type b, meningococcus). Vaccinate (ideally 2 weeks before elective splenectomy) and consider antibiotic prophylaxis.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 71, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Before IV contrast, the nurse checks:', '["Renal function, allergy history, metformin use", "Visual acuity and the use of spectacles", "Hearing and the use of hearing aids", "Hair colour and the use of hair dye"]'::jsonb, 0, 'Hydration reduces contrast nephropathy.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 72, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The inverse square law in radiation protection means that doubling the distance from the source:', '["Has no effect", "Doubles the dose", "Halves the dose", "Reduces the dose to one quarter"]'::jsonb, 3, 'Distance is a simple, powerful protection.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 73, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'On a chest X-ray, the tip of a central venous catheter should lie in the:', '["Inside the right ventricle cavity", "In the left subclavian vein", "High in the internal jugular vein", "Lower SVC, just above the right atrium"]'::jsonb, 3, 'A tip in the atrium may cause arrhythmias or perforation.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 74, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'When transferring a ventilated patient for CT, the nurse should:', '["Portable monitoring, oxygen, suction and emergency drugs", "Send the patient without a nurse to save staff", "Stop all infusions until the patient returns", "Disconnect all monitoring to make the transfer faster"]'::jsonb, 0, 'Transfers are high-risk periods.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 75, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'MRI scanning uses:', '["Ultraviolet light", "Gamma rays", "X-rays", "A strong magnetic field and radio waves, without ionising radiation"]'::jsonb, 3, 'Metal objects can become dangerous projectiles.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 76, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A thyroid shield is worn by theatre staff during fluoroscopy to:', '["Protect the radiosensitive thyroid gland", "Prevent infection", "Support the head", "Keep the neck warm"]'::jsonb, 0, 'Lead glasses protect the eye lens.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 77, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A nasogastric tube''s position should be confirmed before feeding by:', '["The patient''s verbal comfort report only", "Tube colour", "Auscultation (''whoosh test'') alone", "pH testing of aspirate and/or X-ray confirmation"]'::jsonb, 3, 'Best practice for confirming NG tube position is pH testing of aspirate (ideally ≤5.5) and/or radiographic confirmation — auscultation alone is unreliable and is no longer recommended as a sole method.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 78, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Basic radiological principles in the critically ill patient include selecting the imaging type based primarily on:', '["The clinical indication and the specific diagnostic question being asked", "Patient preference alone", "Whichever machine is nearest, regardless of clinical question", "Cost only, with no regard to diagnostic yield"]'::jsonb, 0, 'Choice of imaging modality (X-ray, CT, ultrasound, MRI) should be guided by the clinical indication and what diagnostic information is actually needed.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 79, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A lead apron should be stored:', '["Stored damp after cleaning", "Folded tightly in a drawer", "Piled on the floor of theatre", "Hung or laid flat, never folded"]'::jsonb, 3, 'Folding causes cracks in the lead lining, reducing protection.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 80, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Pneumoperitoneum after laparoscopy usually:', '["Requires surgery", "Always means perforation", "Resolves within a few days", "Never occurs"]'::jsonb, 2, 'Clinical correlation is required.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 81, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Intravenous urography (IVU) is used to visualise the:', '["Brain and spinal cord", "Kidneys, ureters and bladder", "Liver and biliary tree", "Heart and great vessels"]'::jsonb, 1, 'Contrast is injected and filtered by the kidneys.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 82, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A classic chest X-ray sign of pleural effusion is:', '["Blunting of the costophrenic angle", "Free air under the diaphragm", "Hyperinflated lung fields", "A widened mediastinum"]'::jsonb, 0, 'Fluid accumulating in the pleural space characteristically blunts (obscures) the normally sharp costophrenic angle on an upright chest X-ray.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 83, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Before a contrast CT, the nurse checks:', '["Eye colour and any contact lenses worn", "Hair length and any hair products used", "Allergies, renal function and metformin use", "Shoe size and walking ability before CT"]'::jsonb, 2, 'Iodinated contrast can cause allergic reactions and contrast-induced nephropathy.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 84, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Air bronchograms on chest X-ray indicate:', '["A pneumothorax with collapse of the lung", "Normal lung with clear, aerated air spaces", "A pleural effusion at the lung base", "Air-filled bronchi within consolidated lung"]'::jsonb, 3, 'Seen in pneumonia and ARDS.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 85, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Bat-wing perihilar shadowing with Kerley B lines suggests:', '["Massive pulmonary embolism", "Right lower lobe pneumonia", "Tension pneumothorax", "Cardiogenic pulmonary oedema"]'::jsonb, 3, 'Upper lobe venous diversion and effusions may also be seen.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 86, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A CVP line check X-ray is also used to exclude:', '["Acute appendicitis", "Pneumothorax after insertion", "An acute ischaemic stroke", "A fractured femoral neck"]'::jsonb, 1, 'Especially after subclavian or jugular insertion.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 87, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A haemothorax on an erect chest X-ray shows:', '["Free air under the right hemidiaphragm", "A meniscus opacity blunting the costophrenic angle", "A visible lung edge with no markings beyond it", "Hyperinflation with flat diaphragms"]'::jsonb, 1, 'Haemopneumothorax shows a flat air-fluid level.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 88, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'An intravenous urogram (IVU/IVP) shows:', '["The lungs and the pleural spaces", "Kidneys, ureters and bladder after contrast", "The heart chambers and the heart valves", "The brain ventricles and basal cisterns"]'::jsonb, 1, 'It is largely replaced by CT urography.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 89, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A transudate (clear fluid) on CT chest appears as:', '["Hyperdense with strands", "Hyperdense with air densities", "Homogeneously hypodense with no strands", "Hypodense with strands"]'::jsonb, 2, 'Simple transudate appears on CT as homogeneous low-density (water-density) fluid without septations or strands.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 90, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Dilated small bowel loops with multiple air-fluid levels suggest:', '["Gross ascites", "Perforation only", "Small bowel obstruction", "A normal gas pattern"]'::jsonb, 2, 'Valvulae conniventes cross the whole small bowel width.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 91, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Radiographic confirmation of correct nasogastric tube placement shows the tip:', '["Below the diaphragm, in the stomach", "At the level of the carina", "In the right lung field", "Coiled in the oesophagus"]'::jsonb, 0, 'A correctly placed NG tube''s tip is seen on X-ray crossing the diaphragm and lying within the stomach, well below the diaphragm and away from the bronchial tree.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 92, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A chest X-ray after central line insertion is done to:', '["Measure the central venous pressure", "Detect any urinary tract infection", "Check the blood glucose after insertion", "Confirm tip position and exclude pneumothorax"]'::jsonb, 3, 'The tip should be in the lower superior vena cava.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 93, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Radiation protection for the ICU nurse during portable X-ray includes:', '["Standing directly behind the X-ray tube", "Holding the patient still within the beam", "Taking no precautions for portable films", "Standing 2 metres away or wearing a lead apron"]'::jsonb, 3, 'Time, distance and shielding reduce exposure.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 94, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'In theatre, when the image intensifier (C-arm) is used, staff should:', '["Wear lead aprons and thyroid shields, and stand back", "Stand close to the patient without any protection", "Hold the patient''s limb steady within the beam", "Remove lead aprons so as to work faster and cooler"]'::jsonb, 0, 'Doubling distance reduces exposure to one quarter (inverse square law).', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 95, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The FAST scan in trauma is used to detect:', '["Brain injury and skull fractures", "Free fluid in the abdomen or pericardium", "Soft tissue and skin infections", "Fractures of the pelvis and long bones"]'::jsonb, 1, 'It is rapid and done at the bedside.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 96, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Ultrasound is useful in ICU to:', '["Replace every CT scan in the ICU", "Measure the ICP directly at the bedside", "Guide line insertion; assess fluid, lungs, heart", "Diagnose all fractures in trauma patients"]'::jsonb, 2, 'Point-of-care ultrasound is widely used.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 97, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Before a patient has a contrast CT, the nurse checks:', '["Hair colour", "Shoe size", "Favourite food", "Kidney function, allergy history and metformin use"]'::jsonb, 3, 'Contrast can harm kidneys and cause reactions.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 98, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Using ultrasound guidance for central line insertion primarily helps to:', '["Replace the need for a post-procedure chest X-ray in all cases", "Eliminate the need for sterile technique", "Visualise the vein in real time and reduce mechanical complications", "Increase radiation exposure"]'::jsonb, 2, 'Real-time ultrasound guidance allows direct visualisation of the target vein and needle tip, reducing complications such as arterial puncture, pneumothorax, and failed cannulation attempts.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 99, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Before administering iodinated contrast, the standard test dose protocol is to give:', '["1ml, then wait 5 minutes before proceeding", "The full dose immediately with no test", "10ml, then wait 30 minutes", "A test dose only in children"]'::jsonb, 0, 'A 1ml test dose is given, followed by a 5-minute wait to observe for an early reaction, before proceeding with the full contrast dose.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 100, 'Anaesthesia Nursing Mock — Day 5 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'MRI scanning is contraindicated in patients with:', '["Cotton clothing with no metal parts", "Some pacemakers, metal in the eye, some implants", "A plaster of Paris cast on the forearm", "Removable acrylic dentures in the mouth"]'::jsonb, 1, 'MRI uses a strong magnetic field. Metal objects become projectiles and implants may heat or malfunction.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(2, 1, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which of the following is not an ideal characteristic of a volatile anaesthetic agent?', '["Safe for all ages and in pregnancy", "Cheap to manufacture", "Flammable", "Odourless or pleasant to inhale"]'::jsonb, 2, 'Flammability is a dangerous, undesirable property — not an ideal characteristic of a volatile anaesthetic.', 'NAP 413 · Applied Pharmacology I'),
(2, 2, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient receiving cyclosporine post-transplant has hypertension. Which drug is CONTRAINDICATED?', '["Nifedipine", "Lisinopril", "Verapamil", "Amlodipine"]'::jsonb, 2, 'Verapamil increases cyclosporine levels via CYP3A4 inhibition, risking toxicity.', 'NAP 413 · Applied Pharmacology I'),
(2, 3, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Rocuronium-induced neuromuscular block can be rapidly reversed by:', '["Sugammadex", "Dantrolene", "Neostigmine alone at any depth of block", "Suxamethonium"]'::jsonb, 0, 'Sugammadex binds rocuronium directly. Neostigmine works only for shallow block and is given with glycopyrrolate.', 'NAP 413 · Applied Pharmacology I'),
(2, 4, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Prophylactic antibiotics for surgery are most effective when given:', '["After the wound is closed", "Three days before surgery", "Only if the patient develops fever", "Within 60 minutes before skin incision"]'::jsonb, 3, 'Tissue levels must be high at the time of contamination. Doses are repeated in long operations or with major blood loss. Prolonged courses increase resistance without benefit.', 'NAP 413 · Applied Pharmacology I'),
(2, 5, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Prophylactic antibiotics given before surgery are ideally administered:', '["Only if the patient develops a fever post-operatively", "Only after the wound is closed", "More than 6 hours before incision", "Within about 60 minutes before surgical incision"]'::jsonb, 3, 'Surgical antibiotic prophylaxis is most effective when given within roughly 60 minutes before incision, ensuring adequate tissue levels at the time of surgery.', 'NAP 413 · Applied Pharmacology I'),
(2, 6, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Protamine sulfate is used to reverse the anticoagulant effect of:', '["Heparin", "Clopidogrel", "Warfarin", "Aspirin"]'::jsonb, 0, 'Protamine sulfate binds and neutralises heparin, reversing its anticoagulant effect.', 'NAP 413 · Applied Pharmacology I'),
(2, 7, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Ketamine may increase:', '["Heart rate, blood pressure and salivation", "Bronchospasm and hypotension", "Seizure threshold in all patients", "Respiratory depression more than opioids"]'::jsonb, 0, 'Give with an antisialagogue if secretions are a problem.', 'NAP 413 · Applied Pharmacology I'),
(2, 8, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Patient-controlled analgesia (PCA) is safe mainly because:', '["Relatives and visitors can press the button for the patient", "There is no maximum dose, so pain is always fully relieved", "It contains no opioid, so respiratory depression cannot occur", "A sedated patient cannot press, and the lockout limits doses"]'::jsonb, 3, 'Only the patient may press the demand button. Nurses monitor pain, sedation, respiratory rate, SpO2 and the pump settings regularly.', 'NAP 413 · Applied Pharmacology I'),
(2, 9, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient with myasthenia gravis is prescribed neostigmine. The nurse should monitor for:', '["Serotonin syndrome", "Cholinergic crisis", "Thyroid storm", "Neuroleptic malignant syndrome"]'::jsonb, 1, 'Overdose of acetylcholinesterase inhibitors (e.g., neostigmine) causes cholinergic crisis (SLUDGE syndrome).', 'NAP 413 · Applied Pharmacology I'),
(2, 10, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Bronchodilator nebulisers (e.g. salbutamol) can cause which common side effect that the nurse should monitor for?', '["Tachycardia and tremor", "Weight gain", "Bradycardia and sedation", "Hypoglycaemia"]'::jsonb, 0, 'Beta-2 agonist bronchodilators commonly cause tachycardia and fine tremor as expected sympathomimetic side effects.', 'NAP 413 · Applied Pharmacology I'),
(2, 11, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'One milligram (1mg) is prescribed, tablets are 500 micrograms: how many tablets will you give?', '["2tabs", "2mg", "2µs", "2µg"]'::jsonb, 0, '1mg = 1000mcg; 1000mcg ÷ 500mcg per tablet = 2 tablets.', 'NAP 413 · Applied Pharmacology I'),
(2, 12, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Suxamethonium should be avoided in a patient who is 5 days post major burn because of the risk of:', '["Hypocalcaemia and tetany", "Severe hyperkalaemia and cardiac arrest", "Severe hypoglycaemia and seizures", "Prolonged hypertension only"]'::jsonb, 1, 'Burns, crush injury, denervation and prolonged immobility increase muscle acetylcholine receptors.', 'NAP 413 · Applied Pharmacology I'),
(2, 13, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Morphine''s most dangerous side effect after surgery is:', '["Respiratory depression", "Rebound hypertension", "Severe diarrhoea", "Malignant hyperthermia"]'::jsonb, 0, 'Sedation level and respiratory rate are monitored. Increasing sedation is an early warning that precedes respiratory depression. Other effects include nausea, itching, constipation and urinary retention.', 'NAP 413 · Applied Pharmacology I'),
(2, 14, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which of the following drugs inhibits thyroid hormone synthesis preoperatively?', '["Propanolol", "Adrenaline", "Dopamine", "Carbimazole"]'::jsonb, 3, 'Carbimazole blocks thyroid peroxidase, reducing new hormone synthesis before surgery.', 'NAP 413 · Applied Pharmacology I'),
(2, 15, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Insulin for a diabetic patient fasting for surgery is managed by:', '["Stopping all insulin for a week before and after the operation", "Giving oral glucose drinks only, until the patient eats again", "Adjusted doses or a variable rate insulin infusion with glucose checks", "Giving the full usual morning dose of insulin without any food"]'::jsonb, 2, 'Type 1 diabetics always need some insulin to prevent ketoacidosis. Capillary glucose is checked frequently and the patient listed early on the theatre list.', 'NAP 413 · Applied Pharmacology I'),
(2, 16, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Low molecular weight heparin is reversed only partially by:', '["Flumazenil", "Vitamin K", "Protamine sulfate", "Naloxone"]'::jsonb, 2, 'Its anti-Xa effect is not fully reversed.', 'NAP 413 · Applied Pharmacology I'),
(2, 17, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A nurse is monitoring a sedated patient in the ICU using the Richmond Agitation-Sedation Scale (RASS). A score of 0 on the RASS indicates:', '["Unarousable", "Agitated or restless", "Light sedation", "Alert and calm"]'::jsonb, 3, 'The RASS score ranges from -5 (unarousable) to +4 (combative). A score of 0 signifies a patient who is alert, calm, and able to interact appropriately. The other options correspond to different scores on the scale.', 'NAP 413 · Applied Pharmacology I'),
(2, 18, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Clopidogrel is usually stopped before elective surgery because it:', '["Raises blood glucose and causes diabetic ketoacidosis", "Interacts dangerously with all anaesthetic agents", "Irreversibly inhibits platelets and increases bleeding", "Causes severe rebound hypertension under anaesthesia"]'::jsonb, 2, 'It is usually stopped about 7 days before surgery. Patients with recent coronary stents must not stop it without cardiology advice because of the risk of stent thrombosis.', 'NAP 413 · Applied Pharmacology I'),
(2, 19, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The pharmacy needs 500 mL of a 5% dextrose solution but only has 50% dextrose stock solution and sterile water available. How much of the 50% stock solution is needed?', '["5 mL of stock, diluted with 495 mL water", "50 mL of stock, diluted with 450 mL water", "250 mL of stock, diluted with 250 mL water", "100 mL of stock, diluted with 400 mL water"]'::jsonb, 1, 'Using C1V1 = C2V2: 50% x V1 = 5% x 500 mL, so V1 = 2500/50 = 50 mL of stock, topped up with 450 mL diluent to make 500 mL.', 'NAP 413 · Applied Pharmacology I'),
(2, 20, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'An early sign of malignant hyperthermia under anaesthesia is:', '["A fall in heart rate and blood pressure", "An unexplained rise in end-tidal CO₂", "Pinpoint pupils", "A falling body temperature"]'::jsonb, 1, 'Stop triggering agents, give dantrolene 2.5 mg/kg IV and cool the patient.', 'NAP 413 · Applied Pharmacology I'),
(2, 21, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient on a β-blocker has hypoglycemia. Which sign may be masked?', '["Diaphoresis", "Tachycardia", "Tremors", "Hunger"]'::jsonb, 1, 'β-blockers blunt tachycardia (adrenergic response) in hypoglycemia.', 'NAP 413 · Applied Pharmacology I'),
(2, 22, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Drugs that suppress or relieve coughing without necessarily treating the cause are:', '["Antibiotics", "Antitussive agents", "Expectorants", "Bronchodilators"]'::jsonb, 1, 'Antitussives suppress the cough reflex without treating the underlying cause.', 'NAP 413 · Applied Pharmacology I'),
(2, 23, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Hyperkalaemia after suxamethonium is a particular danger in patients with:', '["Burns, crush injury or spinal cord injury after the first 24–48 hours", "Simple appendicitis", "Well-controlled hypertension", "Mild asthma"]'::jsonb, 0, 'Extra-junctional receptors release more potassium.', 'NAP 413 · Applied Pharmacology I'),
(2, 24, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The local anaesthetic most suitable for intravenous regional anaesthesia (Bier''s block) is:', '["Cocaine", "Prilocaine", "Tetracaine", "Bupivacaine"]'::jsonb, 1, 'Bupivacaine is cardiotoxic and must never be used for Bier''s block.', 'NAP 413 · Applied Pharmacology I'),
(2, 25, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Glycopyrrolate differs from atropine because it:', '["Is a muscarinic agonist", "Causes more sedation and confusion", "Does not cross the blood–brain barrier", "Has no effect on secretions"]'::jsonb, 2, 'It is a quaternary amine.', 'NAP 413 · Applied Pharmacology I'),
(2, 26, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The antidote for paracetamol overdose is:', '["Acetylcysteine", "Flumazenil", "Atropine", "Naloxone"]'::jsonb, 0, 'Acetylcysteine replenishes liver glutathione, helping detoxify the harmful paracetamol breakdown product.', 'NAP 413 · Applied Pharmacology I'),
(2, 27, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A urine test in an undiagnosed diabetic may show........', '["B glucose and high amounts of bilirubin in the urine", "D ketones and adrenaline in the urine", "A Glucose and ketones in the urine", "C Ketones and oxalate in the urine"]'::jsonb, 2, 'Glucose and ketones in urine are classic undiagnosed diabetes findings.', 'NAP 413 · Applied Pharmacology I'),
(2, 28, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The nurse is caring for a patient who is on a continuous infusion of Propofol. The nurse should be aware that the infusion should be changed every:', '["24 hours", "48 hours", "72 hours", "12 hours"]'::jsonb, 3, 'Propofol is a lipid-based medication, which makes it a perfect medium for bacterial growth. The infusion and tubing must be changed every 12 hours to reduce the risk of a bloodstream infection.', 'NAP 413 · Applied Pharmacology I'),
(2, 29, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which class of immunosuppressant medications, including tacrolimus and cyclosporine, inhibits calcineurin to reduce T-cell activation but carries a significant risk of nephrotoxicity?', '["Calcineurin inhibitors", "Induction antibody agents", "Antimetabolites, such as mycophenolate", "Corticosteroids"]'::jsonb, 0, 'Calcineurin inhibitors such as tacrolimus and cyclosporine block T-cell activation by inhibiting calcineurin-dependent IL-2 production, but are also directly nephrotoxic and require careful therapeutic drug monitoring to balance rejection prevention with drug-induced kidney injury.', 'NAP 413 · Applied Pharmacology I'),
(2, 30, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A client with asthma is taking a theophylline bronchodilator. Which breakfast item should the nurse discuss with the client?', '["Toast", "Coffee", "Bananas", "Eggs"]'::jsonb, 1, 'Caffeine, like theophylline, is a methylxanthine. Coffee can add to theophylline''s stimulant and toxic effects (tachycardia, tremor).', 'NAP 413 · Applied Pharmacology I'),
(2, 31, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient receiving dexmedetomidine for sedation may experience:', '["Bradycardia and hypotension", "Respiratory depression", "Hypertension and tachycardia", "Agitation"]'::jsonb, 0, 'Dexmedetomidine (α2-agonist) causes sympatholysis, leading to bradycardia/hypotension.', 'NAP 413 · Applied Pharmacology I'),
(2, 32, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient is prescribed an ACE inhibitor for hypertension. The nurse should monitor for which characteristic side effect?', '["Improved potassium excretion with no monitoring needed", "Hair loss", "Significant weight gain only", "Persistent dry cough"]'::jsonb, 3, 'ACE inhibitors are classically associated with a persistent dry cough (related to bradykinin accumulation), a common reason for switching to an ARB if troublesome.', 'NAP 413 · Applied Pharmacology I'),
(2, 33, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which antibacterial should be avoided with d-tubocurarine because it enhances neuromuscular blockade?', '["Norfloxacin", "Doxycycline", "Streptomycin", "Cefotaxime"]'::jsonb, 2, 'Aminoglycosides such as streptomycin reduce acetylcholine release and potentiate non-depolarising blockers, prolonging paralysis.', 'NAP 413 · Applied Pharmacology I'),
(2, 34, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which of these drugs is used as an antidote for narcotics', '["Black charcoal", "Nalaxone", "Atropine", "Cimetidine"]'::jsonb, 1, 'Naloxone is the antidote for narcotic (opioid) overdose.', 'NAP 413 · Applied Pharmacology I'),
(2, 35, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Pethidine is avoided in repeated doses because its metabolite norpethidine can cause:', '["Seizures", "Skin rash only", "Bradycardia only", "Hypoglycaemia"]'::jsonb, 0, 'Norpethidine accumulates especially in renal failure.', 'NAP 413 · Applied Pharmacology I'),
(2, 36, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'If an airway fire occurs during surgery, the first actions are to:', '["Increase oxygen to 100% and continue with surgery", "Increase the oxygen to 100%, keep the tube in and continue the operation", "Stop gas flow, remove the tube and pour saline into the airway", "Leave the tube in place and wait for senior help"]'::jsonb, 2, 'Then ventilate with air, re-intubate and assess the airway.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 37, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient develops excessive bleeding postoperatively. What should be the initial nursing action?', '["Elevating the affected limb", "Applying pressure to the bleeding site", "Providing a warm compress", "Administering more pain medication"]'::jsonb, 1, 'Direct pressure over the bleeding site is the initial action to control postoperative bleeding.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 38, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient has a PCA and becomes very drowsy with RR 8/min. After calling for help and giving oxygen, the nurse should:', '["Stop the PCA and prepare naloxone", "Encourage the patient to press the button", "Increase the PCA bolus", "Give an IV sedative"]'::jsonb, 0, 'Sedation score rises before respiratory depression.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 39, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Exsanguination with an Esmarch bandage before tourniquet inflation should be avoided when there is:', '["Normal, healthy limb skin", "Infection or a tumour in the limb", "A planned knee arthroscopy", "A clean ligament repair of the knee in a young adult"]'::jsonb, 1, 'Squeezing could spread infection, tumour cells or emboli.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 40, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Cell salvage during surgery means:', '["Removing blood before surgery for later transfusion", "Giving plasma expanders only, without any blood products at all", "Giving donor blood that is stored inside the theatre", "Collecting, washing and returning the patient''s own blood"]'::jsonb, 3, 'It is often acceptable to Jehovah''s Witnesses and reduces donor blood use.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 41, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Early signs of local anaesthetic systemic toxicity (LAST) include:', '["Hypothermia and shivering only, without any neurological change", "Increased urine output, thirst and a rising blood sugar level", "Rash and itching only, with wheeze around the injection site", "Circumoral numbness, metallic taste, tinnitus and lightheadedness"]'::jsonb, 3, 'Toxicity progresses to agitation, seizures, then cardiac arrhythmias and arrest. Injection is stopped, help called, airway and seizures managed, and 20% lipid emulsion given.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 42, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The laryngeal mask airway (LMA) differs from an endotracheal tube in that it:', '["Is suitable only for children because of its design", "Passes through the vocal cords and seals the trachea", "Must always be inserted with a laryngoscope blade", "Sits over the larynx and does not fully prevent aspiration"]'::jsonb, 3, 'LMAs are used for short fasted cases with spontaneous breathing. They are avoided in patients at high aspiration risk, such as full stomach or emergency abdominal surgery.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 43, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Urine output in an adult post-operatively should be at least:', '["50 mL per day", "0.5 mL/kg/hour", "5 mL/kg/hour", "0.1 mL/kg/hour"]'::jsonb, 1, 'Lower outputs suggest hypovolaemia or renal impairment. Check catheter patency before assuming oliguria.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 44, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Ketorolac or other NSAIDs are useful in PACU because they:', '["Reduce opioid requirements", "Cause deep sedation, so less monitoring is needed", "Reverse muscle relaxants", "Prevent hypothermia"]'::jsonb, 0, 'Avoid in renal impairment, bleeding risk and asthma sensitive to NSAIDs.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 45, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Reflective practice after a difficult ICU case helps nurses to:', '["Forget the event as fast as possible", "Find someone else to blame", "Learn from experience and improve care", "Avoid learning from the event"]'::jsonb, 2, 'Models such as Gibbs'' cycle guide reflection.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 46, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Before every anaesthetic, the anaesthetic machine should be:', '["Checked only by the surgeon at the Time Out, after the patient is draped", "Used without checks if it worked normally for the last case the day before", "Checked only once a month by the biomedical engineer, not before each case", "Checked with a standard checklist covering gases, leaks, suction and backup"]'::jsonb, 3, 'Checks cover gas supplies and pipelines, vaporiser filling, breathing system leaks, ventilator, monitors, suction, and the availability of a self-inflating bag and backup oxygen.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 47, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Pressure area care in PACU is important because:', '["Patients have been immobile under anaesthesia and are at risk", "Pressure areas are only a ward concern and not a recovery concern", "Anaesthesia protects the skin by improving the local circulation", "Pressure injuries only develop after several weeks of bed rest"]'::jsonb, 0, 'Skin over bony prominences is checked and documented; any damage from positioning in theatre is reported.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 48, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Polypropylene (Prolene) is commonly chosen for vascular anastomosis because it is:', '["Braided, so it holds knots very easily", "Rapidly absorbed by the body within 7 days", "Non-absorbable, smooth and causes little reaction", "Made from purified animal intestine and rapidly absorbed"]'::jsonb, 2, 'Its monofilament surface passes smoothly through vessels.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 49, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Monitor alarms in PACU should be:', '["Set to suitable limits and checked before silencing", "Turned off to reduce noise in the busy unit", "Silenced permanently during the night shift", "Set to the widest possible limits for all patients to reduce noise"]'::jsonb, 0, 'Alarm fatigue causes missed deterioration.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 50, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Abdominal swabs are counted and bagged in:', '["Tens, counted silently by the surgeon at the end of the operation", "Random groups, counted at the very end", "Any number, counted by one person alone", "Fives, counted aloud by two nurses together"]'::jsonb, 3, 'Two people count visibly and audibly, using a standard system.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 51, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient who had spinal anaesthesia complains of a headache in PACU. The nurse should first:', '["Assess the headache and vital signs, and tell the anaesthetist", "Sit the patient up straight and ignore the complaint", "Give a large dose of IV morphine straight away and lie the patient flat", "Discharge the patient to the ward without review"]'::jsonb, 0, 'True post-dural puncture headache usually appears later and is postural.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 52, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A closed suction drain (e.g. Redivac) works by:', '["Keeping the wound edges open for packing", "Letting fluid flow out by gravity into the dressing", "Applying negative pressure to remove fluid from the wound", "Pumping antibiotic solution into the wound to prevent infection"]'::jsonb, 2, 'Note the drain type, amount and colour of drainage on the chart.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 53, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Monofilament sutures have a lower infection risk than braided ones because they:', '["Are thicker and stronger than braids", "Are always absorbable, so no foreign material stays in the body", "Have no gaps where bacteria can hide", "Are coated with an antibiotic layer"]'::jsonb, 2, 'Braided sutures can ''wick'' bacteria, but they handle and knot more easily.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 54, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Enhanced recovery (ERAS) recommends that most patients should be given:', '["Nothing by mouth from the morning of the day before", "Clear carbohydrate drinks up to 2 hours before anaesthesia", "Full bowel preparation before every single operation", "A heavy meal up to 1 hour before going to theatre, to give energy for surgery"]'::jsonb, 1, 'It reduces insulin resistance and patient discomfort.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 55, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Oxygen given by face mask in PACU should be at a flow of at least:', '["1 L/min, as for nasal cannula", "0.5 L/min, to save oxygen and prevent drying of the airway", "60 L/min, the maximum flow", "5 L/min, to avoid rebreathing CO₂"]'::jsonb, 3, 'Lower flows let exhaled CO₂ build up in the mask.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 56, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Propofol as an induction agent is characterised by:', '["Being the treatment for malignant hyperthermia", "Causing hypertension in most patients", "Rapid onset, rapid recovery, and antiemetic properties", "Slow onset and long duration of action"]'::jsonb, 2, 'Propofol has a rapid onset and offset due to fast redistribution and metabolism, and it has mild antiemetic properties, making it popular for induction and maintenance.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 57, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A diabetic patient in PACU is sweating, confused and tachycardic. The nurse should first check:', '["Capillary blood glucose", "Serum sodium and potassium levels", "A chest X-ray film", "Urine culture result"]'::jsonb, 0, 'Hypoglycaemia is quickly treatable with IV glucose.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 58, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The pin-index safety system on gas cylinders is designed to:', '["Show by a colour change when the cylinder is nearly empty", "Measure the pressure of the gas remaining inside the cylinder", "Prevent the wrong gas cylinder being fitted to the machine yoke", "Warm the gas as it leaves the cylinder to prevent hypothermia"]'::jsonb, 2, 'Each gas has a unique arrangement of pins and holes. Colour coding and labelling are additional safety features; Nigeria uses international colours (oxygen is white shoulder).', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 59, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Depolarizing block may be done by:', '["Atracurium", "Succinylcholine", "rocuronuim", "Neostegmin"]'::jsonb, 1, 'Succinylcholine produces its neuromuscular block by persistent depolarisation of the motor endplate.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 60, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Opioid respiratory depression in PACU is reversed safely by:', '["Titrating small IV doses of naloxone", "Giving flumazenil as the specific antidote", "Giving 2 mg naloxone at once to all patients", "Giving more morphine to settle the patient"]'::jsonb, 0, 'Large doses cause severe pain and hypertension; naloxone may wear off before the opioid.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 61, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Which patient should be transferred from PACU to HDU or ICU rather than the ward?', '["One needing ongoing vasopressor support", "One who is awake and talking", "One with stable observations and mild pain", "One who has passed urine"]'::jsonb, 0, 'Use agreed criteria and escalation pathways.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 62, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A PACU nurse receives a patient after spinal anaesthesia for knee surgery. Monitoring should include:', '["BP, block regression and urine output", "Only the respiratory rate each hour", "Only the patient''s appetite and thirst", "Only the wound site and dressing"]'::jsonb, 0, 'Urinary retention is common after spinal anaesthesia.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 63, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Hypoxaemia in PACU after a long abdominal operation is commonly due to:', '["Excess oxygen therapy causing oxygen toxicity in the lungs", "Diuresis causing dehydration and thick bronchial secretions", "Hyperthermia increasing the oxygen demand of the tissues", "Atelectasis and hypoventilation from residual drugs or pain"]'::jsonb, 3, 'Oxygen therapy, sitting up when safe, deep breathing, good analgesia and early mobilisation prevent and treat atelectasis.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 64, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient is experiencing post-operative pain. What nursing interventions can be implemented to help manage the patient''s pain effectively?', '["Encourage the patient to tough it out and not ask for pain medication", "Limit the patient''s fluid intake to decrease discomfort", "Apply heat to the surgical site to alleviate pain", "Administer pain medication as ordered and assess pain levels regularly"]'::jsonb, 3, 'Regularly scheduled analgesia with ongoing pain reassessment is the mainstay of effective postoperative pain control.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 65, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A nurse is caring for a patient who is on a continuous sedative infusion. The nurse knows that the sedative should be weaned slowly to prevent:', '["Withdrawal symptoms and rebound anxiety", "The patient from feeling pain", "A sudden increase in blood pressure", "The patient from waking up too quickly"]'::jsonb, 0, 'A patient on a continuous sedative infusion for a prolonged period can become dependent on the medication. If the sedative is discontinued abruptly, the patient may experience withdrawal symptoms and rebound anxiety. The infusion should be weaned slowly to prevent these complications.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 66, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Sterile drapes, once placed, should:', '["Be adjusted towards the incision whenever needed", "Not be moved, as moving them spreads contamination", "Be lifted to check the skin underneath regularly", "Be shaken out well over the patient before use, then adjusted often"]'::jsonb, 1, 'If a drape is misplaced, discard it and apply a new one.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 67, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU has a heart rate of 38/min with hypotension. The first-line drug is:', '["Amiodarone 300 mg IV", "Atropine 0.5 mg IV", "Metoprolol 5 mg IV", "Adenosine 6 mg IV"]'::jsonb, 1, 'Repeat as needed; look for causes such as vagal stimulation or high spinal.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 68, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Oxygen therapy in PACU is commonly continued until the patient:', '["Has eaten a full meal on the ward", "Maintains target SpO₂ on room air", "Leaves the hospital to go home", "Has had a bowel movement after surgery"]'::jsonb, 1, 'Target is usually 94–98% (88–92% in CO₂ retainers).', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 69, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU says ''I can''t breathe'' but has normal SpO₂ and talks in full sentences. The nurse should:', '["Intubate immediately to protect the airway", "Assess fully, reassure and look for a cause", "Ignore the complaint, as an SpO₂ that is normal means there is no problem", "Give a sedative straight away to calm them"]'::jsonb, 1, 'Anxiety is common but must not be assumed.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 70, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Scrubbed staff should keep their hands:', '["Behind the back, away from the field", "Between chest and waist level, in front of the body", "Below the waist, so the arms can relax", "Tucked into the axillae to keep them warm and away from the sterile field"]'::jsonb, 1, 'Anything below the waist or out of sight is considered unsterile.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 71, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'COVID-19 was declared a pandemic on:', '["11 March 2020", "30 January 2020", "13 March 2020", "27 March 2020"]'::jsonb, 0, 'WHO declared COVID-19 a pandemic on 11 March 2020, after declaring a PHEIC on 30 January 2020.', 'GSM 410 · Applied Microbiology'),
(2, 72, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'After using a hypodermic needle, the correct action is to:', '["Bend the needle to prevent re-use, then discard it into the general waste bin", "Recap it carefully with both hands, then discard it into the yellow clinical waste", "Discard it at once, without recapping, into a sharps container at the point of use", "Place it on the instrument tray so that it is removed at the end of the case"]'::jsonb, 2, 'Most needlestick injuries happen during recapping or disposal. Sharps containers should be at the point of use and closed when three-quarters full. In theatre, use a neutral zone or tray for passing sharps.', 'GSM 410 · Applied Microbiology'),
(2, 73, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The most resistant form of microbial life to heat and chemicals, apart from prions, is:', '["Fungal yeasts", "Enveloped viruses", "Bacterial spores", "Vegetative Gram-positive bacteria"]'::jsonb, 2, 'Spores (Clostridium, Bacillus) have thick protective coats and survive boiling and many disinfectants. Enveloped viruses (HIV, hepatitis B) are the most easily destroyed.', 'GSM 410 · Applied Microbiology'),
(2, 74, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A high white cell count with many neutrophils most often suggests:', '["Viral infection always", "Anaemia", "Allergy only", "Bacterial infection"]'::jsonb, 3, 'Lymphocytes rise more in viral infections.', 'GSM 410 · Applied Microbiology'),
(2, 75, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The organism most commonly responsible for surgical site infections is:', '["Escherichia coli", "Pseudomonas aeruginosa", "Staphylococcus aureus", "Streptococcus pneumoniae"]'::jsonb, 2, 'Staph aureus (a Gram-positive coccus in clusters), often carried in the nose and on the skin, is the leading cause of SSI, especially in clean surgery. Gut organisms dominate after bowel surgery.', 'GSM 410 · Applied Microbiology'),
(2, 76, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Medical management of the client with diverticulitis should include which of the following treatments?', '["Reduced fluid intake.", "Exercises to increase intra-abdominal pressure.", "Increased fiber in the diet.", "Administration of antibiotics"]'::jsonb, 3, 'Antibiotics are a core treatment for the infective/inflammatory component of diverticulitis.', 'GSM 410 · Applied Microbiology'),
(2, 77, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Typhoid fever is caused by:', '["Clostridium tetani", "Vibrio cholerae", "Shigella", "Salmonella Typhi"]'::jsonb, 3, 'It can cause ileal perforation needing surgery.', 'GSM 410 · Applied Microbiology'),
(2, 78, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'When removing (doffing) PPE after caring for an isolated patient, the correct order is:', '["Hand hygiene only, with no specific PPE removal order", "Mask first, then gloves, then gown", "Gown first, followed immediately by mask with no hand hygiene between", "Gloves, goggles, gown, mask, hand hygiene"]'::jsonb, 3, 'PPE doffing removes the most contaminated items first: gloves, then goggles, then gown, then mask, with hand hygiene performed at the end (and often between steps).', 'GSM 410 · Applied Microbiology'),
(2, 79, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The ''golden age'' of antibiotic discovery occurred during which period?', '["2000–present", "1980–2000", "1940–1965", "1900–1920"]'::jsonb, 2, 'Most major antibiotic classes still in use today were discovered during this productive mid-20th-century period.', 'GSM 410 · Applied Microbiology'),
(2, 80, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Fever caused by infection is mainly due to:', '["The kidneys failing to clear excess heat", "Pyrogens acting on the hypothalamus", "The lungs only", "Low blood sugar"]'::jsonb, 1, 'Pyrogens reset the body temperature set point.', 'GSM 410 · Applied Microbiology'),
(2, 81, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The target hand hygiene compliance rate in ICU settings is generally considered to be:', '[">10%", ">50%", "Compliance targets are not tracked", ">90%"]'::jsonb, 3, 'Given how critical hand hygiene is to preventing HAIs, a high compliance target (over 90%) is the goal, even though actual ICU compliance is often suboptimal.', 'GSM 410 · Applied Microbiology'),
(2, 82, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A bacteriostatic antibiotic is one that:', '["Kills bacteria directly", "Has no effect on bacteria at all", "Kills only viruses", "Stops bacteria from multiplying"]'::jsonb, 3, 'Bactericidal drugs kill bacteria.', 'GSM 410 · Applied Microbiology'),
(2, 83, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Surgical site infection risk is reduced by keeping the patient:', '["Very anaemic, with a low haemoglobin", "Hyperglycaemic", "Warm (normothermic) during surgery", "Cold during surgery"]'::jsonb, 2, 'Hypothermia reduces immune function.', 'GSM 410 · Applied Microbiology'),
(2, 84, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The hepatitis B vaccination course for health workers is usually given at:', '["0, 1, 2 and 3 years", "A single dose at birth only", "0, 1 and 6 months", "0 and 12 months only"]'::jsonb, 2, 'Three doses at 0, 1 and 6 months (an accelerated schedule exists), followed by a check of anti-HBs antibody level 1–2 months after completion to confirm immunity.', 'GSM 410 · Applied Microbiology'),
(2, 85, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Hepatitis B surface antibody (anti-HBs) above 10 mIU/mL after vaccination means:', '["The person is a carrier", "The vaccine failed", "The person has active hepatitis", "The person is immune"]'::jsonb, 3, 'Non-responders may need repeat vaccination.', 'GSM 410 · Applied Microbiology'),
(2, 86, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'ICU patients account for approximately what proportion of all hospital-acquired infections, despite occupying fewer than 10% of beds?', '[">50%", ">5%", ">20%", ">90%"]'::jsonb, 2, 'This striking disparity highlights how disproportionately vulnerable ICU patients are to hospital-acquired infection.', 'GSM 410 · Applied Microbiology'),
(2, 87, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Hepatitis C is mainly transmitted by:', '["Food and water", "Blood-to-blood contact", "Mosquito bites", "Coughing and sneezing near others"]'::jsonb, 1, 'There is no vaccine; needlestick injury is a risk.', 'GSM 410 · Applied Microbiology'),
(2, 88, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The preferred route for surgical antibiotic prophylaxis is:', '["Oral", "Systemic (IV)", "Topical only", "Intramuscular only"]'::jsonb, 1, 'IV administration achieves reliable, adequate blood and tissue levels quickly, right when they''re needed.', 'GSM 410 · Applied Microbiology'),
(2, 89, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Normal skin flora such as Staphylococcus epidermidis can cause infection mainly of:', '["Healthy intact skin", "Implants and IV lines", "The eyes only", "The stomach lining in healthy adults"]'::jsonb, 1, 'They form biofilms on plastic and metal.', 'GSM 410 · Applied Microbiology'),
(2, 90, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The chain of infection includes the agent, reservoir, portal of exit, mode of transmission, portal of entry and:', '["Susceptible host", "Sterile equipment", "Healthy staff", "Clean environment"]'::jsonb, 0, 'Breaking any link stops transmission.', 'GSM 410 · Applied Microbiology'),
(2, 91, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'What is the primary cause of septic shock?', '["Medication allergy", "Poison", "Bleeding", "Infection(Blood)"]'::jsonb, 3, 'Septic shock is driven by infection (usually bloodstream).', 'GSM 410 · Applied Microbiology'),
(2, 92, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', '''Protective Environment'' precautions, used for severely immunocompromised patients, rely on:', '["Positive pressure rooms", "No special ventilation", "Open-door policy", "Negative pressure rooms"]'::jsonb, 0, 'Positive pressure keeps outside contaminated air from entering the room, protecting the vulnerable patient inside — the opposite of airborne precaution rooms.', 'GSM 410 · Applied Microbiology'),
(2, 93, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Fungal infections in hospital patients are more likely in those who:', '["Never take antibiotics", "Have short day surgery", "Have central lines, broad-spectrum antibiotics or immunosuppression", "Are young and healthy, with short day-case surgery and no antibiotics"]'::jsonb, 2, 'Candida species are the most common.', 'GSM 410 · Applied Microbiology'),
(2, 94, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Hepatitis A is mainly spread by:', '["Sexual contact only", "Airborne droplets", "Blood transfusion only", "The faecal-oral route"]'::jsonb, 3, 'Good hygiene and vaccination prevent it.', 'GSM 410 · Applied Microbiology'),
(2, 95, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A blood culture should be taken:', '["Before starting antibiotics, using strict aseptic technique", "From the arm with the drip running, after the first antibiotic dose", "After antibiotics are given", "Without skin cleaning"]'::jsonb, 0, 'Contamination causes false-positive results.', 'GSM 410 · Applied Microbiology'),
(2, 96, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The most appropriate statements concerning the pathophysiology and clinical presentation of necrotizing fasciitis include:', '["In Necrotizing fasciitis, the infection begins at the junction between the dermis and the superficial fascia.", "Despite extensive infection of underlying fascia in the early pathological stages, the skin is likely to appear normal.", "The presence of skin bullae, blisters and skin fluctuation suggests early disease.", "The most critical early distinctive symptom of necrotizing fasciiti is that, there is no disproportionate level of pain compared with physical findings."]'::jsonb, 1, 'Overlying skin can look deceptively normal despite extensive underlying fascial infection in early necrotizing fasciitis.', 'GSM 410 · Applied Microbiology'),
(2, 97, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A patient develops a urinary tract infection after an indwelling urinary catheter has been inserted. This would most accurately be termed as which type of infection?', '["An opportunistic infection", "A chronic infection", "An iatrogenic infection", "A viral infection"]'::jsonb, 2, 'An infection caused by a medical device/procedure is termed iatrogenic.', 'GSM 410 · Applied Microbiology'),
(2, 98, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The nurse has opened the sterile supplies and put on two sterile gloves to complete a sterile dressing change, a procedure that requires surgical asepsis. The nurse must:', '["Keep splashes on the sterile field to a minimum.", "Cover the nose and mouth with gloved hands if a sneeze is imminent.", "Use forceps soaked in a disinfectant.", "Consider the outer 1 inch of the sterile field as contaminated."]'::jsonb, 3, 'The outer 1 inch of a sterile field is always considered contaminated.', 'GSM 410 · Applied Microbiology'),
(2, 99, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'For surgical prophylaxis, the antibiotic dose should ideally be given:', '["Timing does not matter", "More than 2 hours before surgery", "Just before surgery", "Only after the surgery is completed"]'::jsonb, 2, 'Giving the dose just before incision ensures adequate drug levels are present in the tissue during the highest-risk period; more than 2 hours before is considered wasted timing.', 'GSM 410 · Applied Microbiology'),
(2, 100, 'Anaesthesia Nursing Mock — Day 5 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Majority of patients admitted into CCU tends to be highly vulnerable to nosocomial infections during their stay in the unit. As a critical care nurse you know this is mostly due to:', '["The critical illness", "Low immunity", "Lack of love ones", "Malnutrition"]'::jsonb, 1, 'Critical illness itself suppresses immune function, making low immunity the main driver of nosocomial infection risk in the CCU.', 'GSM 410 · Applied Microbiology'),
(3, 1, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Kubler-Ross''s stages of grief are:', '["Shock, surprise, anger, acceptance, joy", "Acceptance, denial, anger, depression, bargaining", "Denial, anger, bargaining, depression and acceptance", "Anger, denial, depression, acceptance, bargaining"]'::jsonb, 2, 'Not all patients go through every stage in order.', 'GSB 410 · Applied Behavioural Science'),
(3, 2, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'The ''sick role'' described by Parsons includes the right to be excused from normal duties and the duty to:', '["Seek help and try to get well", "Hide the illness", "Stay ill as long as possible", "Refuse all treatment"]'::jsonb, 0, 'Society expects the sick person to cooperate with care.', 'GSB 410 · Applied Behavioural Science'),
(3, 3, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Benner''s ''From Novice to Expert'' model describes:', '["Stages of clinical competence", "Stages of wound healing", "Stages of a surgical operation", "Phases of general anaesthesia"]'::jsonb, 0, 'It is used for training and mentoring of theatre nurses.', 'GSB 410 · Applied Behavioural Science'),
(3, 4, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'The method and process of facilitating the peaceful ending of a conflict is called:', '["Conflict resolution", "Psychological trauma", "Fight", "Conflict"]'::jsonb, 0, 'Conflict resolution is the process of bringing a conflict to a peaceful end.', 'GSB 410 · Applied Behavioural Science'),
(3, 5, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'The self-care deficit theory was proposed by:', '["Betty Neuman", "Imogene King", "Virginia Henderson", "Dorothea Orem"]'::jsonb, 3, 'Dorothea Orem proposed the self-care deficit theory.', 'GSB 410 · Applied Behavioural Science'),
(3, 6, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A client develops an autoimmune reaction that attacks her own joint tissue. Using Neuman''s classification, this stressor would be categorized as:', '["Suprapersonal", "Interpersonal", "Intrapersonal", "Extrapersonal"]'::jsonb, 2, 'An intrapersonal stressor arises from within the individual, such as an internal physiological or emotional process; an autoimmune reaction occurring within the client''s own body fits this category.', 'GSB 410 · Applied Behavioural Science'),
(3, 7, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Health belief model suggests that people take health action when they:', '["Believe they are at risk and the benefits outweigh the barriers", "Have no knowledge of the illness", "Are told to without explanation", "Have no symptoms or risk"]'::jsonb, 0, 'It helps plan patient education.', 'GSB 410 · Applied Behavioural Science'),
(3, 8, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Body image changes after surgery such as mastectomy or stoma may cause:', '["No emotional effect at all", "Grief, low self-esteem and depression", "Increased self-esteem in every case", "Improved mood and confidence only"]'::jsonb, 1, 'Counselling and support groups help.', 'GSB 410 · Applied Behavioural Science'),
(3, 9, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Socialisation is the process by which:', '["People learn the norms and values of their group", "Infectious diseases spread through a group", "People become isolated from their society", "Hospitals and clinics are built in a community"]'::jsonb, 0, 'Professional socialisation shapes nursing identity.', 'GSB 410 · Applied Behavioural Science'),
(3, 10, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Maslow''s self-actualisation refers to:', '["Meeting basic bodily needs", "Being loved and accepted", "Feeling safe and secure", "Realising one''s full potential"]'::jsonb, 3, 'It is the top of the hierarchy.', 'GSB 410 · Applied Behavioural Science'),
(3, 11, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A client who has managed a chronic illness for many years tells the nurse, ''I''ve learned so much about myself through this journey, and I feel I''ve grown into the best version of myself.'' This statement best reflects which level of Maslow''s hierarchy?', '["Physiological needs", "Self-actualization needs", "Self-esteem needs", "Safety and security needs"]'::jsonb, 1, 'Self-actualization, the highest level in Maslow''s hierarchy, involves realizing one''s fullest potential, personal growth, and self-fulfillment — reflected in this client''s sense of personal growth through adversity.', 'GSB 410 · Applied Behavioural Science'),
(3, 12, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Erikson''s stage for adolescents is:', '["Trust versus mistrust", "Integrity versus despair", "Industry versus inferiority", "Identity versus role confusion"]'::jsonb, 3, 'Body image after surgery is especially important to teenagers.', 'GSB 410 · Applied Behavioural Science'),
(3, 13, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Displacement means:', '["Making excuses for behaviour", "Blocking memories completely", "Behaving the opposite of one''s feelings", "Redirecting feelings onto a safer target"]'::jsonb, 3, 'E.g. shouting at the nurse after bad news from the doctor.', 'GSB 410 · Applied Behavioural Science'),
(3, 14, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Non-verbal communication includes:', '["Emails", "Written reports only", "Facial expression, posture and eye contact", "Telephone calls only"]'::jsonb, 2, 'It often carries more meaning than words.', 'GSB 410 · Applied Behavioural Science'),
(3, 15, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A patient is admitted to the ICU following a suicide attempt by drug overdose. Once medically stabilised, the nurse''s priority alongside physical care is to:', '["Focus exclusively on physical recovery with no psychological assessment", "Discharge the patient as soon as vital signs normalise, with no further assessment", "Assess psychiatric risk, ensure a safe environment, and involve mental health/psychiatric services", "Avoid discussing the event with the patient entirely"]'::jsonb, 2, 'Care after a suicide attempt must include psychiatric risk assessment, ensuring a safe environment (e.g. removing means of harm), and timely involvement of mental health services, alongside physical stabilisation.', 'GSB 410 · Applied Behavioural Science'),
(3, 16, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Behavioural Science is defined by the American Psychological Association as:', '["Subject of studying human behaviours.", "Discipline that uses systemic observation and experimentation in the scientific study of human and non-human actions and reactions.", "Discipline of applied behavioural analysis which involves applying behavioural principles in practice setting.", "A discipline in which humans relate with their environment."]'::jsonb, 1, 'APA defines behavioural science as the systematic scientific study of human/non-human actions and reactions.', 'GSB 410 · Applied Behavioural Science'),
(3, 17, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A hospitalized client repeatedly asks the nurse to keep the bed rails up and the call light within reach, expressing fear of falling. This behavior is best explained by which level of Maslow''s hierarchy?', '["Self-actualization needs", "Love and belonging needs", "Physiological needs", "Safety and security needs"]'::jsonb, 3, 'Concerns about physical safety and protection from harm, such as fear of falling, correspond to the safety and security level of Maslow''s hierarchy, which follows physiological needs.', 'GSB 410 · Applied Behavioural Science'),
(3, 18, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Neuman describes three levels of prevention as intervention. Which level is aimed at strengthening the flexible line of defense BEFORE a stressor invades the client system?', '["Quaternary prevention", "Secondary prevention", "Primary prevention", "Tertiary prevention"]'::jsonb, 2, 'Primary prevention in Neuman''s model occurs before a stressor has invaded the system, aiming to reduce the possibility of encountering the stressor or to strengthen the flexible line of defense, such as through immunization or health teaching.', 'GSB 410 · Applied Behavioural Science'),
(3, 19, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Regression is when a patient:', '["Channels feelings into useful activity", "Becomes more mature and independent", "Returns to behaviour of an earlier stage", "Blames other people for own feelings"]'::jsonb, 2, 'Common in children and stressed adults.', 'GSB 410 · Applied Behavioural Science'),
(3, 20, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Stress in theatre staff can be reduced by:', '["Ignoring feelings so work continues", "Blaming others when things go wrong", "Increasing the workload to build strength", "Teamwork, adequate breaks and support"]'::jsonb, 3, 'Debriefing after critical incidents helps.', 'GSB 410 · Applied Behavioural Science'),
(3, 21, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Betty Neuman''s systems model focuses on:', '["Self-care deficits and nursing systems", "Interpersonal phases of the relationship", "Environmental cleanliness and fresh air only", "Responses to stressors and lines of defence"]'::jsonb, 3, 'Prevention is primary, secondary or tertiary.', 'GSR 410 · Research Methodology & Statistics'),
(3, 22, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Assigning numbers to objects or events according to a set of rules is termed:', '["Numbering", "Sampling", "Observation", "Measurement"]'::jsonb, 3, 'Measurement is assigning numbers to objects or events according to rules.', 'GSR 410 · Research Methodology & Statistics'),
(3, 23, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A nurse researcher notices a rising rate of pressure ulcers in immobile ICU patients and decides to investigate the issue. This scenario best illustrates the research process step of', '["Reporting research findings", "Data analysis", "Formulating recommendations", "Problem identification"]'::jsonb, 3, 'Noticing and defining a gap or issue in practice worth investigating is the problem identification step, the starting point of the research process.', 'GSR 410 · Research Methodology & Statistics'),
(3, 24, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A patient''s choices, preferences and decisions are assessed under:', '["Values and beliefs", "Nutrition and metabolism", "Self-perception and self-concept", "Cognition and perception"]'::jsonb, 0, 'The values–beliefs pattern covers the patient''s values, goals, choices and spiritual beliefs that guide decisions.', 'GSR 410 · Research Methodology & Statistics'),
(3, 25, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which is a characteristic of quantitative research?', '["Data are reported in a literary style", "There are multiple subjective realities", "A large sample is emphasised", "No generalisation is made from the findings"]'::jsonb, 2, 'Quantitative research stresses large, representative samples and generalisation. Multiple subjective realities and literary reporting are qualitative features.', 'GSR 410 · Research Methodology & Statistics'),
(3, 26, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'In order to achieve objective, organisations should apply the method of science to solve problems, with specific reference to operational research and advanced mathematical technique. This statement implies:', '["Management by objective", "Classical theory", "Behavioural theory", "System theory"]'::jsonb, 3, 'Applying scientific/mathematical methods to solve organisational problems reflects systems theory.', 'GSR 410 · Research Methodology & Statistics'),
(3, 27, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which step of the research process cuts across all the other steps?', '["Literature review", "Research variables", "Hypothesis", "Problem identification"]'::jsonb, 0, 'The literature review runs through the whole research process, from framing the problem to discussing findings.', 'GSR 410 · Research Methodology & Statistics'),
(3, 28, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A test''s sensitivity is the proportion of:', '["Patients with the disease who test positive", "Positive tests that are true positives", "All tests that are correct", "Patients without the disease who test negative"]'::jsonb, 0, 'High sensitivity rules out disease when the test is negative (SnOut).', 'GSR 410 · Research Methodology & Statistics'),
(3, 29, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Quality assurance in ICU uses Donabedian''s framework of:', '["Planning, organising and controlling", "Input, output and feedback only", "Structure, process and outcome", "Assessment, diagnosis and planning"]'::jsonb, 2, 'Structure: resources; process: activities; outcome: results.', 'GSR 410 · Research Methodology & Statistics'),
(3, 30, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'All arithmetic operations (add, subtract, multiply, divide) can be performed on which scale?', '["Ordinal", "Interval", "Ratio", "Nominal"]'::jsonb, 2, 'Only the ratio scale has a true zero, so all arithmetic, including ratios, is meaningful (e.g. weight, height).', 'GSR 410 · Research Methodology & Statistics'),
(3, 31, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Research conducted to find a solution to an immediate problem is:', '["Analytical research", "Action research", "A survey", "Fundamental research"]'::jsonb, 1, 'Action research is done to find a solution to an immediate, practical problem in a setting.', 'GSR 410 · Research Methodology & Statistics'),
(3, 32, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'When nurses help clients explore lifestyle habits and health behaviours to identify health risks, they are using which model?', '["Psychosocial model", "Medical model", "Wellness model", "Physiological model"]'::jsonb, 2, 'Wellness models look at lifestyle and health behaviours to identify risks and promote health.', 'GSR 410 · Research Methodology & Statistics'),
(3, 33, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The gold-standard method for confirming initial placement of a blindly inserted nasogastric or orogastric feeding tube before starting feeds is:', '["Observing the patient for coughing during insertion only", "Auscultation of air insufflation over the epigastrium (the \"whoosh test\")", "Abdominal or chest X-ray", "Checking that the external tube length looks approximately correct"]'::jsonb, 2, 'Radiographic confirmation (X-ray) is the gold standard for verifying correct placement of a blindly inserted feeding tube before the first feeding or medication is given, since auscultation alone is unreliable and can miss tracheobronchial placement.', 'GSR 410 · Research Methodology & Statistics'),
(3, 34, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The hypothesis that states there is no difference between groups is the:', '["Conceptual framework", "Alternative hypothesis", "Research question", "Null hypothesis"]'::jsonb, 3, 'Statistical tests assess evidence against the null hypothesis. A p-value below 0.05 is commonly taken as significant.', 'GSR 410 · Research Methodology & Statistics'),
(3, 35, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'At the ratio level of measurement, the most appropriate index of central tendency is usually the:', '["Range", "Median", "Mean", "Mode"]'::jsonb, 2, 'For interval or ratio data that are roughly symmetrical, the mean is the most appropriate measure of central tendency.', 'GSR 410 · Research Methodology & Statistics'),
(3, 36, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which is NOT a probability sampling method?', '["Cluster sampling", "Stratified random sampling", "Simple random sampling", "Convenience sampling"]'::jsonb, 3, 'Convenience sampling is non-probability. Simple random, cluster and stratified sampling give every unit a known chance of selection.', 'GSR 410 · Research Methodology & Statistics'),
(3, 37, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A Blue print of Research work is called', '["Research tools", "Research methods", "Research design", "Research Problem"]'::jsonb, 2, 'A structured overall plan for conducting research is the research design.', 'GSR 410 · Research Methodology & Statistics'),
(3, 38, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The Glasgow Coma Scale (GCS) score, which ranks a patient''s level of consciousness from 3 to 15, is best classified as which scale of measurement?', '["Ordinal", "Interval", "Nominal", "Ratio"]'::jsonb, 0, 'The GCS ranks levels of consciousness in order, but the difference between successive scores does not represent an equal clinical interval, making it an ordinal scale.', 'GSR 410 · Research Methodology & Statistics'),
(3, 39, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'On the periodic table, which element used in contrast media has the highest atomic number of the three commonly referenced in radiology (iodine, barium, gadolinium)?', '["Barium (56)", "They are all equal", "Iodine (53)", "Gadolinium (64)"]'::jsonb, 3, 'Gadolinium has atomic number 64, higher than barium (56) and iodine (53) — gadolinium is used specifically for MRI contrast, not X-ray/CT.', 'GSR 410 · Research Methodology & Statistics'),
(3, 40, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Per current evidence-based critical care nutrition guidance, gastric residual volume (GRV) monitoring should generally prompt the nurse to hold or reassess feeding when the volume exceeds approximately:', '["50 mL", "GRV should never be checked regardless of volume", "1500 mL", "500 mL"]'::jsonb, 3, 'Current guidance from major critical care nutrition societies suggests holding or reassessing feeds when GRV exceeds approximately 500 mL, since routinely stopping feeds at lower volumes has not been shown to reduce aspiration risk and can lead to unnecessary underfeeding.', 'GSR 410 · Research Methodology & Statistics'),
(3, 41, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A population that consists of an endless succession of values is:', '["A sample", "Infinite", "Finite", "Definitive"]'::jsonb, 1, 'A population with an endless (uncountable) succession of values is infinite.', 'GSR 410 · Research Methodology & Statistics'),
(3, 42, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Postural drainage uses gravity to:', '["Improve the patient''s appetite and feeding", "Drain secretions from specific lung segments", "Reduce the intracranial pressure after injury", "Increase the blood pressure in hypotension"]'::jsonb, 1, 'Head-down positions are avoided in raised ICP.', 'GSR 410 · Research Methodology & Statistics'),
(3, 43, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which scale of measurement captures data in mutually exclusive categories with no order?', '["Ratio", "Ordinal", "Nominal", "Interval"]'::jsonb, 2, 'The nominal scale puts data into mutually exclusive, unordered categories.', 'GSR 410 · Research Methodology & Statistics'),
(3, 44, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Research control means holding constant other influences that might affect the:', '["Conditioned variable", "Independent variable", "Antecedent variable", "Dependent variable"]'::jsonb, 3, 'Research control holds extraneous influences constant so that changes in the dependent variable can be put down to the independent variable.', 'GSR 410 · Research Methodology & Statistics'),
(3, 45, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which of these is NOT a qualitative variable?', '["Age", "Marital status", "Sex", "Religion"]'::jsonb, 0, 'Age is a quantitative variable. Sex and marital status are qualitative (categorical).', 'GSR 410 · Research Methodology & Statistics'),
(3, 46, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient’s advance directive states no intubation. During respiratory arrest, the nurse should:', '["Start non-invasive ventilation", "Follow the advance directive", "Ask family for consent", "Intubate emergently"]'::jsonb, 1, 'Advance directives are legally binding; providers must honor them.', 'GSE 410 · Ethico-Legal Issues'),
(3, 47, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient’s family asks about autopsy after death. The nurse states:', '["\"Autopsy requires consent.\"", "\"Autopsy is unnecessary.\"", "\"Autopsy is only for forensic cases.\"", "\"Autopsy is mandatory.\""]'::jsonb, 0, 'Autopsy requires informed consent from next of kin.', 'GSE 410 · Ethico-Legal Issues'),
(3, 48, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Beneficence means:', '["Telling the patient the truth", "Doing good for the patient", "Treating patients fairly", "Avoiding harm to the patient"]'::jsonb, 1, 'Non-maleficence means avoiding harm; justice is fairness.', 'GSE 410 · Ethico-Legal Issues'),
(3, 49, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient''s confidential information may be disclosed in which instance?', '["To pay the patient''s hospital bill", "In order to take him to the hospital", "To tell the doctor the truth", "To prevent harm or grievous injury"]'::jsonb, 3, 'Confidential information may be disclosed without consent when needed to prevent serious harm to the patient or others, or when required by law.', 'GSE 410 · Ethico-Legal Issues'),
(3, 50, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient with advanced cancer requests discontinuation of chemotherapy. The nurse supports this decision based on:', '["Justice", "Autonomy", "Beneficence", "Nonmaleficence"]'::jsonb, 1, 'Autonomy respects the patient''s right to self-determination.', 'GSE 410 · Ethico-Legal Issues'),
(3, 51, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'What is the most common source of malpractice for nurses?', '["Privacy violations", "Medication errors", "HIPPA complaints", "Negligent delegation"]'::jsonb, 1, 'Medication errors are the most commonly cited source of nursing malpractice claims.', 'GSE 410 · Ethico-Legal Issues'),
(3, 52, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Which four elements must all be proven for a nurse to be found legally negligent?', '["Consent, capacity, communication, and confidentiality", "Intent, motive, opportunity, and consequence", "Only that harm occurred, regardless of cause", "Duty of care, breach of duty, harm, and breach causing the harm"]'::jsonb, 3, 'Negligence requires proof of all four elements: a duty of care existed, that duty was breached, harm resulted, and the breach directly caused the harm.', 'GSE 410 · Ethico-Legal Issues'),
(3, 53, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A leadership style that allows the opinion of the majority of group members is:', '["Bureaucratic", "Autocratic", "Laissez-faire", "Democratic"]'::jsonb, 3, 'Democratic leaders involve the group and go with majority opinion.', 'GSE 410 · Ethico-Legal Issues'),
(3, 54, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A nursing instructor tells students that the most important principle when caring for patients is to do no harm. This principle is:', '["Beneficence", "Non-maleficence", "Justice", "Veracity"]'::jsonb, 1, 'Non-maleficence means "first, do no harm". It runs from the Hippocratic Oath to the Nightingale Pledge.', 'GSE 410 · Ethico-Legal Issues'),
(3, 55, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'In which category does management fall?', '["Emerging profession", "Semi-profession", "Well-established profession", "Marginal profession"]'::jsonb, 0, 'Management lacks some features of a full profession (such as compulsory licensing), so it is regarded as an emerging profession.', 'GSE 410 · Ethico-Legal Issues'),
(3, 56, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'For an unconscious patient needing emergency life-saving surgery with no relatives, surgery may proceed under:', '["Consent signed by the theatre porter", "No surgery until a relative is found", "Waiting for the patient to wake up", "Necessity, in the patient''s best interests"]'::jsonb, 3, 'Documentation must explain the emergency.', 'GSE 410 · Ethico-Legal Issues'),
(3, 57, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A critically-ill patient has a "Living Will" in the chart. The patient''s condition has deteriorated, but the spouse wants "everything done" regardless of the patient''s wishes. Which ethical principle is the spouse violating?', '["Justice", "Non-maleficence", "Beneficence", "Autonomy"]'::jsonb, 3, 'Overriding a patient''s documented wishes (Living Will) disregards their autonomy.', 'GSE 410 · Ethico-Legal Issues'),
(3, 58, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Helsinki Declaration establishes that:', '["Science''s interests always come first", "Consent is optional if the research benefits many people", "Subject wellbeing takes precedence over the interests of science/society", "Only adult subjects may ever be studied"]'::jsonb, 2, 'This declaration puts the individual research subject''s welfare above any broader scientific or societal gain.', 'GSE 410 · Ethico-Legal Issues'),
(3, 59, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A retained surgical instrument is legally:', '["A breach of duty that can lead to a negligence claim", "The patient''s fault for moving during surgery", "A minor issue that needs no report or follow-up", "Acceptable if the operation was very difficult"]'::jsonb, 0, 'Counting procedures prevent retained items; discrepancies must be resolved before closure.', 'GSE 410 · Ethico-Legal Issues'),
(3, 60, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Breach of patient confidentiality without lawful justification may expose a nurse to which type of legal action?', '["Civil liability for breach of confidentiality/privacy", "Automatic loss of citizenship", "No consequence, since nurses have full immunity", "Only a verbal warning with no formal process"]'::jsonb, 0, 'Unjustified disclosure of confidential patient information can expose a nurse to civil liability for breach of confidentiality.', 'GSE 410 · Ethico-Legal Issues'),
(3, 61, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The right to withdraw from a research study at any time is part of the subject''s right to:', '["Data ownership", "Self-determination", "Anonymity only", "Compensation"]'::jsonb, 1, 'Being free to change one''s mind and leave a study without penalty is a core aspect of a subject''s autonomy over their own participation.', 'GSE 410 · Ethico-Legal Issues'),
(3, 62, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A nurse notices a suspicious lesion on a neonate but, knowing it could worsen, does not report it, and the baby is sent home and deteriorates. This is:', '["Advertent negligence", "Inadvertent negligence", "Battery", "Assault"]'::jsonb, 0, 'Advertent negligence: the carer knows the likely harmful consequence of omitting a required action and omits it anyway, e.g. noticing a lesion and not acting.', 'GSE 410 · Ethico-Legal Issues'),
(3, 63, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A patient refuses blood transfusion on religious grounds. The nurse should:', '["Ignore the refusal because life comes first", "Give the blood secretly while the patient is asleep", "Force the patient to accept the transfusion", "Respect the competent adult''s decision and document it"]'::jsonb, 3, 'Autonomy is respected; alternatives such as cell salvage may be discussed.', 'GSE 410 · Ethico-Legal Issues'),
(3, 64, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Nursing and Midwifery Council of Nigeria (NMCN) regulates:', '["Drug manufacturing and importation", "Nursing education and practice in Nigeria", "Medical doctors and their training", "Hospital finances and staff salaries"]'::jsonb, 1, 'It sets standards, registers nurses and handles professional misconduct.', 'GSE 410 · Ethico-Legal Issues'),
(3, 65, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A document that lists the medical treatment a person chooses to refuse if unable to make decisions is the:', '["Advance directives", "Living will", "Durable power of attorney", "Informed consent"]'::jsonb, 1, 'A living will is the advance directive that lists the treatments a person chooses to refuse if they can no longer decide. A durable power of attorney names a proxy decision-maker instead.', 'GSE 410 · Ethico-Legal Issues'),
(3, 66, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Advance directives are:', '["Doctor''s orders written in the treatment chart", "Hospital policies about end-of-life care", "Insurance documents about payment for care", "A competent person''s written wishes about future care"]'::jsonb, 3, 'They must be respected when valid and applicable.', 'GSE 410 · Ethico-Legal Issues'),
(3, 67, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Assault and battery in nursing refers to:', '["Documenting the care given in the nursing notes", "Giving a prescribed drug with the patient''s consent", "Touching or treating a patient without valid consent", "Recording observations accurately on the chart"]'::jsonb, 2, 'Valid consent must be voluntary and informed by a competent person.', 'GSE 410 · Ethico-Legal Issues'),
(3, 68, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'What is informed consent in nursing?', '["The process of respecting patients right to refuse or withdraw from a specific procedure or treatment", "The process of ensuring that a patient understands and agrees to a specific procedure or treatment", "The process of providing information to a patient about the risks and benefits of a specific procedure or treatment", "The process of obtaining permission from a patient to perform a specific procedure or treatment"]'::jsonb, 1, 'Informed consent centres on the patient genuinely understanding and agreeing to a procedure.', 'GSE 410 · Ethico-Legal Issues'),
(3, 69, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The four principles of bioethics are:', '["Autonomy, beneficence, non-maleficence, justice", "Confidentiality, consent, care and cost", "Honesty, kindness, respect and duty", "Safety, quality, efficiency and equity"]'::jsonb, 0, 'These guide ethical decisions in perioperative care.', 'GSE 410 · Ethico-Legal Issues'),
(3, 70, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A competent patient''s living will refuses aggressive cancer treatment, but the physician insists on chemotherapy for the patient''s benefit. The physician is exercising:', '["Ideal beneficence", "Paternalism", "Veracity", "Respect for autonomy"]'::jsonb, 1, 'Paternalism is overriding a competent patient''s known wishes (such as a living will refusing aggressive treatment) "for their own good".', 'GSE 410 · Ethico-Legal Issues'),
(3, 71, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Computers classified by size, from largest to smallest, are:', '["Supercomputer, mainframe, minicomputer, microcomputer", "Server, router, modem, scanner", "Microcomputer, minicomputer, mainframe, supercomputer", "Laptop, desktop, tablet, mainframe"]'::jsonb, 0, 'Most hospital desktops and laptops are microcomputers.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 72, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'The four main functional components of a standard computer are:', '["Laptop, desktop, tablet and hand-held", "Input, process, output and memory (storage)", "Hardware, software, system apps and applications", "Keyboard, mouse, monitor and CPU"]'::jsonb, 1, 'A computer''s four main functional components are input, processing, output and storage (memory).', 'GSC 410 · ICT & Nursing Informatics'),
(3, 73, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Which of the following units of data is the largest?', '["Terabyte (TB)", "Megabyte (MB)", "Kilobyte (KB)", "Gigabyte (GB)"]'::jsonb, 0, 'A Terabyte is the largest unit listed, equal to about one trillion bytes. The order from smallest to largest is: Kilobyte (about one thousand bytes), Megabyte (about one million bytes), Gigabyte (about one billion bytes), and Terabyte.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 74, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'CT scan and ultrasound machines are best classified as which type of healthcare ICT device?', '["Diagnostic devices", "Monitoring devices only", "Communication devices", "Treatment devices only"]'::jsonb, 0, 'CT and ultrasound are used to establish or confirm a diagnosis by producing images of internal structures, making them diagnostic devices.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 75, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'According to function, computers are classified as:', '["Electronic and battery-powered", "Automatic and manual", "Analogue, digital and hybrid", "Laptop, desktop and hand-held"]'::jsonb, 2, 'By function (how they process data), computers are analogue, digital or hybrid.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 76, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'During electronic health documentation, which computer part allows a critical care nurse to enter patient data?', '["Input device", "Operating system", "Output device", "Software"]'::jsonb, 0, 'Input devices (keyboard, mouse, touchscreen, scanner) put data into the computer. Output devices (monitor, printer) display it.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 77, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A barcode scanner used for patient identification is an example of:', '["An input device", "An output device", "A processing device", "A storage device"]'::jsonb, 0, 'Output devices include printers, monitors and speakers.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 78, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'The computer mouse is_________________', '["a storage device", "a processing device", "an input device", "an output device"]'::jsonb, 2, 'The mouse is an input device.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 79, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Which one is NOT an input device?', '["Keyboard", "Mouse", "Scanner", "Monitor"]'::jsonb, 3, 'A monitor is an output device. Mouse, keyboard and scanner are input devices.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 80, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'The central processing unit (CPU) of a computer is the:', '["Display screen showing the output", "Printer used to produce paper copies", "Part that carries out instructions", "Keyboard used to type in data"]'::jsonb, 2, 'Memory stores data; input/output devices interact with users.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 81, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Electronic mail (e-mail) of patient information should be:', '["Encrypted and sent only to authorised people", "Shared in staff group chats for quick advice", "Sent to personal accounts because it is faster", "Printed and posted on the ward notice board"]'::jsonb, 0, 'Confidentiality laws apply to electronic communication.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 82, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'An advantage of the electronic medication administration record (eMAR) over paper MARs is:', '["It requires no cross-check with the pharmacy system", "It cannot be updated in real time", "Real-time updates and reduced transcription error risk", "It eliminates the need for the five rights of administration"]'::jsonb, 2, 'eMAR systems update in real time and are typically integrated with pharmacy and BCMA systems, reducing transcription errors compared to handwritten paper MARs.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 83, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A cardiac monitor and pulse oximeter used in the ICU are examples of which category of electronic devices in healthcare?', '["Treatment devices", "Monitoring devices", "Diagnostic devices", "Storage devices"]'::jsonb, 1, 'Cardiac monitors and pulse oximeters continuously track a patient''s physiological status, placing them in the monitoring devices category.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 84, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'In data transfer process, what does FTP stand for?', '["File transfer protection", "File transfer program", "File transfer Protocol", "File transmission protocol"]'::jsonb, 2, 'FTP is File Transfer Protocol, a standard way of moving files between computers over a network.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 85, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A nurse is setting up a new computer station in a clinic. Which of the following is considered an output device?', '["Mouse", "Printer", "Microphone", "Scanner"]'::jsonb, 1, 'An output device receives data from a computer. A printer produces a hard copy of a document. A mouse, scanner, and microphone are all input devices used to send information into the computer.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 86, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'Which is an example of formal written communication in a hospital?', '["A personal diary", "A text to a friend", "A social media post", "An incident report"]'::jsonb, 3, 'Formal reports must be factual, objective and clear.', 'Use of English & Communication'),
(3, 87, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'The prefix ''hyper-'' means:', '["Around", "Above or excessive", "Without", "Below or deficient"]'::jsonb, 1, 'E.g. hypertension, hyperglycaemia.', 'Use of English & Communication'),
(3, 88, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correctly punctuated sentence:', '["The surgeon''s instruments were ready.", "The surgeons instrument''s were ready.", "The surgeons'' instrument''s were ready.", "The surgeon''s instrument''s were ready."]'::jsonb, 0, 'The apostrophe shows possession, not plurals.', 'Use of English & Communication'),
(3, 89, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'Choose the word closest in meaning to ''ambulate'':', '["Breathe", "Walk", "Eat", "Sleep"]'::jsonb, 1, 'Early ambulation reduces DVT risk.', 'Use of English & Communication'),
(3, 90, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correct preposition: ''The patient was allergic ___ penicillin.''', '["for", "to", "with", "from"]'::jsonb, 1, '''Allergic to'' is the correct collocation.', 'Use of English & Communication'),
(3, 91, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correct form: ''Each of the nurses ___ responsible for the count.''', '["were", "be", "are", "is"]'::jsonb, 3, '''Each'' takes a singular verb.', 'Use of English & Communication'),
(3, 92, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'The plural of ''criterion'' is:', '["Criteria", "Criterions", "Criterias", "Criterium"]'::jsonb, 0, 'Similarly, ''phenomenon'' becomes ''phenomena''.', 'Use of English & Communication'),
(3, 93, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Use of English & Communication', 'Which of these words is spelt correctly?', '["Neccessary", "Necesary", "Necessary", "Neccesary"]'::jsonb, 2, 'One ''c'' and double ''s''.', 'Use of English & Communication'),
(3, 94, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'A sole proprietorship means:', '["A business owned and run by one person", "A company owned by many shareholders", "A business run by a government agency", "A partnership of two or more people"]'::jsonb, 0, 'The owner has unlimited liability.', 'Entrepreneurship'),
(3, 95, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'A business plan should include:', '["Only the owner''s name and the business address", "The hospital''s rules and its staff disciplinary code", "Executive summary, market analysis, finances and marketing", "Personal diaries and family photographs of the owner"]'::jsonb, 2, 'It guides operations and helps secure funding.', 'Entrepreneurship'),
(3, 96, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'Customer satisfaction in a health business is important because it:', '["Has no effect on income", "Encourages repeat use and referrals", "Increases costs only", "Reduces quality"]'::jsonb, 1, 'Feedback helps improve services.', 'Entrepreneurship'),
(3, 97, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'The Corporate Affairs Commission (CAC) in Nigeria:', '["Regulates drugs and food", "Registers businesses and companies", "Licenses nurses and midwives", "Manages public hospitals"]'::jsonb, 1, 'Registration gives legal recognition.', 'Entrepreneurship'),
(3, 98, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'A franchise is a business arrangement in which:', '["Profits go only to charity", "A person pays to use an established brand and system", "The government owns all shares", "There is no brand"]'::jsonb, 1, 'The franchisor gives support and rules.', 'Entrepreneurship'),
(3, 99, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'A partnership business is:', '["Owned by the government only", "A charity with no owners", "Owned by two or more people who share profits and liabilities", "Owned by one person only"]'::jsonb, 2, 'A partnership agreement should be written.', 'Entrepreneurship'),
(3, 100, 'Anaesthesia Nursing Mock — Day 5 Night (Nov 2026)', 'Entrepreneurship', 'An example of a nurse-led business in perioperative care is:', '["Building roads", "Running a bank", "A private home-care service for post-operative patients", "Selling cars"]'::jsonb, 2, 'Nurses can also offer training or consultancy.', 'Entrepreneurship');
