-- Anaesthesia Nursing (Nurse Anaesthetist) mock exams — Day 5 (2026-11-08): 300 questions in 3 papers of 100.
--   Morning (08:00–10:00): NAP 411 · Fundamentals of Nursing Anaesthesia, NAP 410 · Applied Anatomy & Physiology I, NAP 412 · Applied Physics, Chemistry & Radiology
--   Afternoon (12:00–14:00): NAP 413 · Applied Pharmacology I, NAP 414 · Nursing Anaesthesia Practice, GSM 410 · Applied Microbiology
--   Night (19:00–21:00): GSB 410 · Applied Behavioural Science, GSR 410 · Research Methodology & Statistics, GSE 410 · Ethico-Legal Issues, GSC 410 · ICT & Nursing Informatics, Use of English & Communication, Entrepreneurship
-- The questions are added as hidden exam-only questions (not shown in the practice app). The exams are
-- created for the ANAESTHESIA NURSING section only (specialty = 'anaes'), so Critical Care and Perioperative students never see them.
-- Times (Nigeria time) can be changed later on the admin page. If an exam already exists, only its
-- questions are updated. Safe to run more than once.
set lock_timeout = '5s';
begin;
create temporary table ponew (paper int, n int, source text, topic text, q text, opts jsonb, ans_idx int, exp text, category text, primary key (paper, n)) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.paper, d.n), d.topic, d.source, d.q, d.opts, d.ans_idx, d.exp, d.category, '🩺', false
from ponew d
where not exists (select 1 from public.questions x where x.source = d.source and x.q = d.q);
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1), instructions = 'Anaesthesia Nursing — Day 5 Morning. 100 questions: NAP 411 · Fundamentals of Nursing Anaesthesia, NAP 410 · Applied Anatomy & Physiology I, NAP 412 · Applied Physics, Chemistry & Radiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 5 Morning (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 5 Morning (100 Questions)', 'Anaesthesia Nursing — Day 5 Morning. 100 questions: NAP 411 · Fundamentals of Nursing Anaesthesia, NAP 410 · Applied Anatomy & Physiology I, NAP 412 · Applied Physics, Chemistry & Radiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-08 08:00:00+01', timestamptz '2026-11-08 10:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 5 Morning (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2), instructions = 'Anaesthesia Nursing — Day 5 Afternoon. 100 questions: NAP 413 · Applied Pharmacology I, NAP 414 · Nursing Anaesthesia Practice, GSM 410 · Applied Microbiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 5 Afternoon (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 5 Afternoon (100 Questions)', 'Anaesthesia Nursing — Day 5 Afternoon. 100 questions: NAP 413 · Applied Pharmacology I, NAP 414 · Nursing Anaesthesia Practice, GSM 410 · Applied Microbiology. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-08 12:00:00+01', timestamptz '2026-11-08 14:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 5 Afternoon (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3), instructions = 'Anaesthesia Nursing — Day 5 Night. 100 questions: GSB 410 · Applied Behavioural Science, GSR 410 · Research Methodology & Statistics, GSE 410 · Ethico-Legal Issues, GSC 410 · ICT & Nursing Informatics, Use of English & Communication, Entrepreneurship. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'anaes'
 where title = 'Anaesthesia Nursing Mock — Day 5 Night (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Anaesthesia Nursing Mock — Day 5 Night (100 Questions)', 'Anaesthesia Nursing — Day 5 Night. 100 questions: GSB 410 · Applied Behavioural Science, GSR 410 · Research Methodology & Statistics, GSE 410 · Ethico-Legal Issues, GSC 410 · ICT & Nursing Informatics, Use of English & Communication, Entrepreneurship. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-08 19:00:00+01', timestamptz '2026-11-08 21:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3),
       true, true, 100, true, true, 1, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Anaesthesia Nursing Mock — Day 5 Night (100 Questions)');
select title, specialty, cardinality(question_ids) as questions, starts_at, ends_at
  from public.exam_exams where title like 'Anaesthesia Nursing Mock — Day 5 %' order by starts_at;
commit;
